(window.__BOOKS=window.__BOOKS||{})["e_ion"]={"b":[["h2","Действующие лица"],["person","<span class=\"pn\">Гермес</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Ион, сын Феба и <span class=\"ch\" data-ch=\"kreusa\">Креусы</span></span> <span class=\"act-no\">(I)</span>"],["person","<span class=\"pn\">Хор — рабыни <span class=\"ch\" data-ch=\"kreusa\">Креусы</span></span>"],["person","<span class=\"pn\">Креуса, царица афинская</span> <span class=\"act-no\">(II)</span>"],["person","<span class=\"pn\">Ксуф, ее муж</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Старик — дядька <span class=\"ch\" data-ch=\"kreusa\">Креусы</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Раб <span class=\"ch\" data-ch=\"kreusa\">Креусы</span></span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Пифия, дельфийская пророчи- ца</span> <span class=\"act-no\">(III)</span>"],["person","<span class=\"pn\">Афина</span> <span class=\"act-no\">(III)</span>"],["act","Пролог","a1",""],["sd","Сцена представляет свободное пространство перед храмом Аполлона в Дельфах. Фронтон богато изукрашен живописью и скульптурой. В глубине видны горы, ближе к храму — лавровая роща. Рассвет."],["scene","Явление первое","s1",1,1],["sp","Гермес"],["v","Старинный кров бессмертных — небеса, —",0,1,0,0],["v","Лоснящий медью плеч Атлант когда-то",0,1,0,0],["v","Родил с богиней Майю: это мать",0,1,0,0],["v","Моя была, отец мой — Зевс великий.",0,2,0,0],["v","И это я, слуга бессмертных, в Дельфы",0,3,0,0],["v","Пришел, где Феб, заняв срединный храм,<a class=\"nr\" href=\"#n-k1\" data-n=\"k1\" aria-label=\"Примечание 1\">1</a>",0,4,0,0],["v","И что теперь творится, и что будет,",0,5,0,0],["v","Размеренной вещает речью. Есть",0,6,0,0],["v","В Элладе славный город: в честь Паллады,",0,7,0,0],["v","Сверкающей копьем, он наречен.",0,8,0,0],["v","Там Аполлон принудил к браку дочь",0,9,0,0],["v","<span class=\"ch\" data-ch=\"kreusa\">Креусу</span> Эрехтея, под навесом",0,10,0,1],["v","Той северной скалы, где кремль стоит…",0,11,0,0],["sd","(Ск<em>а</em>лам тем имя «Долгих» дали люди.)"],["v","Не знал отец, что дочь его, царевна,",0,12,0,0],["v","От Феба носит бремя; так желал",0,13,0,0],["v","Сам Аполлон. Когда ж настало время,",0,14,0,0],["v","Родив в чертогах сына, нежный плод",0,15,0,0],["v","Под ту же сень, где сочеталась с богом,",0,16,0,0],["v","Царевна отнесла и на смерть сына-",0,17,0,0],["v","Малютку обрядила: в закругленной",0,18,0,0],["v","Положен он корзинке крепкой был…",0,19,0,0],["v","Был соблюден и дедовский обычай",0,20,0,1],["v","Царевною: рожденного землей",0,21,0,0],["v","Когда беречь давала Аглавридам",0,22,0,0],["v","Кронида дочь, она на помощь им",0,23,0,0],["v","Двух змей еще приставила к ребенку;",0,24,0,0],["v","С тех пор в Афинах золоченых змей",0,25,0,0],["v","На шею надевают детям. Этот<a class=\"nr\" href=\"#n-k2\" data-n=\"k2\" aria-label=\"Примечание 2\">2</a>",0,26,0,0],["v","Девичий свой убор надев на сына,",0,27,0,0],["v","Царевна с ним простилась. А ко мне",0,28,0,0],["v","Взмолился брат: \"Ты знаешь край, конечно,",0,29,0,0],["v","Людей тех самородных, край Афины,<a class=\"nr\" href=\"#n-k3\" data-n=\"k3\" aria-label=\"Примечание 3\">3</a>",0,30,0,1],["v","Возьми же — там, в пещере, есть дитя,",0,30,0,0],["v","Рожденное недавно, — там, в корзинке",0,31,0,0],["v","С его приданым детским, — ты малютку",0,32,0,0],["v","К святилищу дельфийскому снеси",0,33,0,0],["v","И положи у входа — это сын мой;",0,34,0,0],["v","Об остальном я позабочусь сам\".",0,35,0,0],["v","И вот, в угоду брату, колыбель",0,36,0,0],["v","Плетеную я поднял и малютку",0,37,0,0],["v","Оставил перед входом в Фебов храм,",0,38,0,0],["v","Убежище из прутьев приоткрывши,",0,39,0,0],["v","Чтоб там дитя заметили.",0,40,0,1],["v","И вслед",1,40,0,0],["v","На небо въехал Гелий, а к порогу",0,40,0,0],["v","Святилища, гляжу, идет жена…",0,41,0,0],["v","И уж войти готова в храм, но взор",0,42,0,0],["v","Роняет на младенца и дивится:",0,43,0,0],["v","Неужто же кто из девиц дерзнул",0,44,0,0],["v","Мучений плод подкинуть тайно богу?",0,45,0,0],["v","«Подальше же младенца от святыни!»",0,46,0,0],["v","Но слезы растопили сердце ей,",0,47,0,0],["v","И сыну Феб помог остаться в храме.",0,48,0,0],["v","Он Пифией был вскормлен, хоть она",0,49,0,0],["v","Не знала, что ребенок этот Фебов,",0,50,0,1],["v","И матери его не знала; также",0,50,0,0],["v","И он не знает, кто родил его.",0,51,0,0],["v","Пока малюткой был он, с алтарей",0,52,0,0],["v","Питаясь, тут он и играл на воле,",0,53,0,0],["v","А как подрос, дельфийцы сторожить<a class=\"nr\" href=\"#n-k4\" data-n=\"k4\" aria-label=\"Примечание 4\">4</a>",0,54,0,0],["v","Сокровища назначили его,",0,55,0,0],["v","И он, храмовник верный, в божьем доме",0,55,0,0],["v","И посейчас живет, от всех почтен.",0,56,0,0],["v","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> ж, мать его, за <span class=\"ch\" data-ch=\"ksuf\">Ксуфа</span> вышла;",0,57,0,0],["v","И вот как это было: меж афинян",0,58,0,0],["v","И жителей Евбеи, что слывут",0,59,0,0],["v","Народом Халкодонта, разлилась<a class=\"nr\" href=\"#n-k5\" data-n=\"k5\" aria-label=\"Примечание 5\">5</a>",0,60,0,1],["v","Враждебная пучина. <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> к Афинам",0,60,0,0],["v","На помощь поспешает, и рука",0,61,0,0],["v","Царевны их и царский сан ему",0,62,0,0],["v","Наградою явились. Сам он не был",0,63,0,0],["v","Из племени афинян, — Эолид",0,63,0,0],["v","И Зевсов внук, он родился в Ахайе.",0,64,0,0],["v","Детей у <span class=\"ch\" data-ch=\"ksuf\">Ксуфа</span> нет, а уж давно",0,65,0,0],["v","Женат он на <span class=\"ch\" data-ch=\"kreusa\">Креусе</span>. В Дельфы их",0,66,0,0],["v","И привело горячее желанье",0,66,0,0],["v","Иметь детей. А Локсий вел к тому,",0,67,0,0],["v","Должно быть, дело, — это все мне ясно.",0,68,0,0],["v","При входе в храм он <span class=\"ch\" data-ch=\"ksuf\">Ксуфу</span> своего",0,69,0,0],["v","Пристроит в сыновья, чтобы в Афинах",0,70,0,1],["v","Он и <span class=\"ch\" data-ch=\"kreusa\">Креусой</span> признан был, и все,<a class=\"nr\" href=\"#n-k6\" data-n=\"k6\" aria-label=\"Примечание 6\">6</a>",0,70,0,0],["v","Что следует ему, из рук их принял,",0,71,0,0],["v","А Фебов брак остался бы в тени.",0,72,0,0],["v","(И эллины на азиатский берег",0,73,0,0],["v","Перенесут царя <span class=\"ch\" data-ch=\"ion\">Иона</span> имя…)",0,74,0,0],["v","Здесь лавров сень я вижу; и она",0,75,0,0],["v","Меня сейчас укроет, с сыном Феба",0,76,0,0],["v","Что сделалось, узнать хочу. Он пыль",0,77,0,0],["v","С ворот смести собрался веткой лавра",0,78,0,0],["v","При входе в храм дельфийца… Назовут",0,79,0,0],["v","Его «<span class=\"ch\" data-ch=\"ion\">Ион</span>», и это имя я",0,80,0,1],["v","Придумал из богов <span class=\"ch\" data-ch=\"ion\">Иону</span> первый…",0,81,0,0],["sd","(Быстро скрывается в рощу.)"],["scene","Явление второе","s2",1,2],["sd","Из правой двери выходит <span class=\"ch\" data-ch=\"ion\">Ион</span>. Это еще юноша. У него пышные золотисто-белые волосы; в одной руке у него несколько связанных вместе лавровых веток, в другой — золотая кропильница; за поясом ключи, через плечо лук и колчан со стрелами. Мимическая сцена. Поставив кропильницу на землю, <span class=\"ch\" data-ch=\"ion\">Ион</span> несколько времени молча смотрит на восток, потом, простирая руки к небу…"],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Четверня с горящей колесницей…",0,82,0,0],["v","Это Гелий огибает землю,",0,83,0,0],["v","И бегут испуганные звезды",0,84,0,0],["v","В лоно свежей ночи.",0,85,0,0],["v","Уж Парнаса, недоступны людям,",0,86,0,0],["v","Нам на радость осветились выси,",0,87,0,0],["v","Уступая солнцу,",0,88,0,0],["v","И безводных в сенях Аполлона",0,89,0,0],["v","Смол клубятся дымы.",0,90,0,1],["v","На треножник села освященный",0,91,0,0],["v","Дельфов дочь и эллинам поет,",0,92,0,0],["v","Фебовы угадывая речи.",0,93,0,0],["v","Вдали слышен неясный шум голосов.",0,94,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","на этот шум"],["v","Вы, дельфийцы, свита Феба, вы!",0,95,0,0],["v","К серебру кружений касталийских<a class=\"nr\" href=\"#n-k8\" data-n=\"k8\" aria-label=\"Примечание 8\">8</a>",0,96,0,0],["v","Поспешайте, чтобы в храм вступить",0,97,0,0],["v","Светлоорошенным…",0,98,0,0],["v","Но уста, сомкнутые во благо,",0,99,0,0],["v","Там для слов лишь Феба отверзайте,",0,100,0,1],["v","Языком божественным рожденных…",0,101,0,0],["v","Мы же здесь, привычным с малолетства,",0,102,0,0],["v","Отдадим трудам себя, и вход",0,103,0,0],["v","В Фебов дом от пыли веткой лавра",0,104,0,0],["v","Мы очистим — свежей веткой лавра",0,105,0,0],["v","Окропим водою плиты, птиц",0,106,0,0],["v","Отпугнем, чтоб портить не летали",0,107,0,0],["v","Светлые дары… Стрелу в крылатых!",0,108,0,0],["sd","Мимика."],["v","Без отца, без матери, кому ж",0,109,0,0],["v","И послужим мы, когда не храму?",0,110,0,1],["v","Это он нас вырастил…",0,111,0,0],["sd","(Принимается за работу.)"],["sd","Пауза."],["str","Строфа"],["v","Ой ты, свежая ветка,",0,112,0,0],["v","Нет на свете прекрасней!",0,113,0,0],["v","Чище мети, о ветка,",0,114,0,0],["v","Фебовы сени…",0,115,0,0],["v","Ты из садов нетленных,",0,116,0,0],["v","Там, где, ключом пробившись",0,117,0,0],["v","Светлым и вечным, поят",0,118,0,0],["v","Росы тот мирт зеленый,",0,120,0,1],["v","Что подарил мне ветку.",0,121,0,0],["v","Дружно с крылом быстрым",0,122,0,0],["v","Солнца мой день проходит…",0,123,0,0],["v","О Пеан, о Пеан, о!",0,124,0,0],["v","Благословен да будет",0,125,0,0],["v","Сын Латоны вовеки!",0,126,0,0],["str","Антистрофа"],["v","Добрым трудом, о боже,",0,127,0,0],["v","Благословенно чту я",0,128,0,0],["v","Трона Вещей преддверье…",0,130,0,1],["v","Славен и труд наш,",0,131,0,0],["v","Если богам мы служим,",0,132,0,0],["v","Вечным богам, не смертным…",0,133,0,0],["v","И не устану, божье",0,134,0,0],["v","Благословляя иго,",0,135,0,0],["v","Славя кормильца Феба…",0,136,0,0],["v","Феб ли меня не нежил?",0,137,0,0],["v","Он ли отцом мне не был?",0,140,0,1],["v","О Пеан, о Пеан, о!",0,141,0,0],["v","Благословен да будет",0,142,0,0],["v","Сын Латоны вовеки!",0,143,0,0],["sd","<span class=\"ch\" data-ch=\"ion\">Ион</span> обметает пол и двери. Пауза. Потом он опускает ветку в воду и кропит ею вокруг."],["str","Эпод"],["v","Довольно влачить листья,",0,144,0,0],["v","Листья лавра по плитам!",0,145,0,0],["v","Из золотых сосудов",0,146,0,0],["v","Пусть источник земной упадет,",0,147,0,0],["v","Касталийскою пеной венчанный,",0,148,0,0],["v","От руки не познавшего ложа…",0,150,0,1],["sd","Пауза. <span class=\"ch\" data-ch=\"ion\">Ион</span> кропит."],["v","Так всегда бы, всю жизнь",0,150,1,0],["v","Только Фебу служить…",0,151,1,0],["v","Если жребий менять, так только на счастье.",0,152,0,0],["v","Мимическая сцена с воображаемыми на сцене птицами.",0,153,0,0],["v","Ба… глядите…",0,154,2,0],["v","Птиц-то, птиц-то летит…",0,155,2,0],["v","Их парнасский покинут ночлег…",0,156,2,0],["v","Гей вы! Прочь!.. Пощадите карниз…",0,157,2,0],["v","Золоченую сень пожалейте…",0,158,2,0],["v","Дальше, дальше, вестник Кронидов!<a class=\"nr\" href=\"#n-k9\" data-n=\"k9\" aria-label=\"Примечание 9\">9</a>",0,159,2,0],["v","Пусть осилил ты клювом кривым",0,160,2,1],["v","Всех крылатых, — стрелы не осилишь…",0,161,2,0],["sd","(Поднимает лук и накладывает стрелу.)"],["v","Вот еще — норовит к алтарю…",0,162,2,0],["v","Это — лебедь! Пурпурные ноги",0,163,2,0],["v","Уноси, белокрылый, отсюда!",0,164,2,0],["v","А не то даже Фебовой лире тебя",0,165,2,0],["v","Не спасти: заглушит ее звон тетива.",0,166,2,0],["v","На делийских озерах спасайся, а здесь<a class=\"nr\" href=\"#n-k10\" data-n=\"k10\" aria-label=\"Примечание 10\">10</a>",0,167,2,0],["v","Как бы кровью, гляди, не окрасить свои",0,168,2,0],["v","Сладкозвучные песни…",0,169,2,0],["v","Ба… а это?.. глядите… а там",0,170,2,1],["v","Что за новая птица?..",0,170,2,0],["v","Иль под самым карнизом она собралась",0,171,2,0],["v","Свить детенышам дом?",0,172,2,0],["sd","(Нацеливается.)"],["v","Эй, смотри, чтобы пение стрел",0,173,2,0],["v","Не спугнуло, крылатый, тебя!..",0,174,2,0],["v","Ты не слушаешь? Нет?",0,175,2,0],["sd","(Натягивает лук.)"],["v","Говорю: на бурливый Алфей улетай,",0,176,2,0],["v","Выводи свою семью в истмийские рощи!",0,177,2,0],["v","А у нас не для вас ярко блещут дары",0,178,2,0],["v","Близ палат Аполлона.",0,179,2,0],["sd","(Опускает и, вновь грозясь, поднимает лук.)"],["v","Только стыдно мне вас убивать,",0,180,2,1],["v","Вы ведь носите людям",0,180,2,0],["v","Олимпийца слова, а не то б…",0,181,2,0],["v","Ой, смотри ты… Я Фебов слуга,",0,182,2,0],["v","И на что для него не дерзну я.",0,183,2,0],["scene","Явление третье","s3",1,3],["sd","На орхестру спускается хор из 15 афинских женщин — спутниц <span class=\"ch\" data-ch=\"kreusa\">Креусы</span>."],["scene","Вступительная песнь хора","s4",1,4],["sd","(в сопровождении мимической сцены)"],["sp","Первое полухорие"],["str","Строфа I"],["v","Нет, не только Паллады град",0,184,0,0],["v","Дивно славен колоннами",0,185,0,0],["v","Храмов или по улицам",0,186,0,0],["v","Красотой изваяний, —",0,187,0,0],["v","Здесь, у сына Латонина,",0,188,0,0],["v","Ярки прелестью дивных глаз",0,189,0,0],["v","Близнецы над воротами.",0,190,0,1],["sp","Второе полухорие"],["v","Посмотри, подивися:",0,190,0,0],["v","Гидру Лерны Кронидов сын",0,191,0,0],["v","Золотой поражает косою.",0,192,0,0],["v","Подойди же, взгляни, сестра.",0,193,0,0],["sp","Первое полухорие"],["str","Антистрофа I"],["v","В самом деле… А рядом с ним",0,194,0,0],["v","Кто-то с факелом пламенным.",0,195,0,0],["v","Помню, часто у кросен ведь",0,196,0,0],["v","Нам о нем говорили:",0,197,0,0],["v","Иолай со щитом своим,",0,198,0,0],["v","Верен сыну Кронидову",0,199,0,0],["v","И в бою и в трудах он был…",0,200,0,1],["sp","Второе полухорие"],["v","Посмотри: это всадник,",0,201,0,0],["v","На коне окрыленном он,",0,202,0,0],["v","С пастью огненной чудище,",0,203,0,0],["v","Трехсоставного зверя разит.",0,204,0,0],["sp","Первое полухорие"],["str","Строфа II"],["v","Здесь глаза разбегаются…",0,205,0,0],["v","Посмотри: бой гигантов там,",0,206,0,0],["v","На стене он на каменной.",0,207,0,0],["sp","Второе полухорие"],["v","Вижу, вижу, подруги!",0,208,0,0],["sp","Первое полухорие"],["v","Это кто ж потрясает щит.",0,209,0,0],["v","К Энкеладу склонив его,",0,210,0,1],["v","И Горгона на нем горит?..",0,210,0,0],["sp","Второе полухорие"],["v","То — Афина-владычица.",0,211,0,0],["sp","Первое полухорие"],["v","А белый этот",0,212,0,0],["v","Порывистый перун в простертой",0,213,0,0],["v","Деснице Зевса, видишь?",0,214,0,0],["sp","Второе полухорие"],["v","Вижу, вижу: на Мима нацелен он",0,215,0,0],["v","На безумного…",0,215,0,0],["v","Вот и Бромия тирсы, увитые",0,216,0,0],["v","Мирным плющом, сынов земли",0,217,0,0],["v","С черным прахом смешали всех.",0,218,0,0],["sp","Хор"],["dir","увидев <span class=\"ch\" data-ch=\"ion\">Иона</span>"],["str","Антистрофа II"],["v","Ты, храмовник, послушай нас…",0,219,0,0],["v","Можно ль белым ногам моим",0,220,0,1],["v","За священный ступить порог?",0,220,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Нет, чужестранки, нет!",0,221,0,0],["sp","Хор"],["v","А спросить тебя можно?",0,221,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О чем меня спросить ты хочешь?",0,222,0,0],["sp","Хор"],["v","Средина земли, она",0,223,0,0],["v","Точно здесь, в доме Фебовом?",0,223,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да, в повязки увитая:",0,224,0,0],["v","Две Горгоны блюдут ее.",0,225,0,0],["sp","Хор"],["v","Так молва и меж нас была.",0,225,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Принесите жертву перед домом,",0,226,0,0],["v","И когда от Феба ждете слова,",0,226,0,0],["v","Так сюда входите, — но без жертвы",0,227,0,0],["v","Входа нет, жена, тебе во храм.",0,228,0,0],["sp","Хор"],["v","Я закон поняла теперь, —",0,228,0,0],["v","И будет сердцу",0,229,0,0],["v","Священным он отныне, верь мне…",0,230,0,1],["v","Смотреть-то позволяют?",0,230,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Все смотри, на что смотреть не грех.",0,231,0,0],["sp","Хор"],["v","Подивиться на храм мы отпущены",0,232,0,0],["v","Господами в ограду дельфийскую.",0,233,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А зовется как господский дом, скажи?",0,233,0,0],["sp","Хор"],["v","Город девы Паллады взрастил меня —",0,234,0,0],["v","Там и царство господ моих…",0,235,0,0],["v","Вот царица сама идет…",0,236,0,0],["act","Действие первое","a2","I"],["scene","Явление четвертое","s5",2,5],["sd","Те же и <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> в сопровождении небольшой свиты. <span class=\"ch\" data-ch=\"ion\">Ион</span> и <span class=\"ch\" data-ch=\"kreusa\">Креуса</span>."],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Твое лицо, о женщина, прекрасно…",0,236,0,0],["v","Мне все равно, откуда ты — души",0,237,0,0],["v","Возвышенной твоей нельзя не видеть…",0,238,0,0],["v","И только кровь чертам людей дает",0,239,0,0],["v","Вот этот отпечаток благородства.",0,240,0,1],["v","Ба… это что ж?..",0,240,0,0],["v","Меня ты поразила: у тебя",0,241,0,0],["v","Глаза заплаканы, и слезы оросили",0,242,0,0],["v","Твои ланиты нежные, едва",0,243,0,0],["v","Храм Вещего тебе открылся… Что же",0,244,0,0],["v","Тебя печалит, женщина?.. Другим",0,245,0,0],["v","Так радостно увидеть рощу бога.",0,246,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты, видно, жил уж сердцем, если ты",0,247,0,0],["v","Мои заметил слезы, чужестранец.",0,248,0,0],["v","Далекие воспоминанья мне",0,249,0,0],["v","Навеял этот вид и роща Феба —",0,250,0,1],["v","Я здесь с тобой, а мысли были дома.",0,250,0,0],["sd","(Про себя.)"],["v","О женщины несчастные и вы,",0,251,0,0],["v","Дерзания бессмертных! Сильный может",0,252,0,0],["v","Губить тебя, а что с него возьмешь?..",0,253,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Загадочен, о женщина, твой гнев…",0,254,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О нет… Мой лук уж спущен, и молчаньем",0,255,0,0],["v","Опять покрыто горе… Позабудь.",0,256,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но кто же ты? Твой край? Отца какого",0,257,0,0],["v","Ты дочь? И как тебя зовут, скажи?",0,258,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","По имени <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> я, отец —",0,259,0,0],["v","Царь Эрехтей, отечество — Афины.",0,260,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Твой славен край. И царственный отец",0,261,0,0],["v","Тебя взрастил… Тебе ль не утешаться?..",0,262,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я счастлива, но только этим, гость.",0,263,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А правда ли?.. Молва такая ходит…",0,264,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Вопроса жду я, друг… Ты хочешь знать?..",0,265,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","То правда ли, что по отцу твой предок",0,266,0,0],["v","Родился из земли, как я слыхал?",0,267,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, Эрихтон то был… Не нам на счастье.",0,268,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И будто он Афиной был повит?",0,269,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Без матери… в руках девичьих… точно.",0,270,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И отдан, если живопись не лжет…",0,270,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","…Был дочерям Кекропа потаенно…",0,271,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но я слыхал, что девушки потом",0,272,0,0],["v","Богинину корзинку растворили…",0,273,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","И кровью их был обагрен утес.",0,274,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Еще бы нет…",0,275,0,0],["v","А тот, другой рассказ… Ведь это ж сказки?<a class=\"nr\" href=\"#n-k13\" data-n=\"k13\" aria-label=\"Примечание 13\">13</a>",0,275,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Какой рассказ?.. Спроси… Я не спешу.",0,276,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","несколько смущенный"],["v","Что твой отец сестер твоих убийца?",0,277,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, в жертву их за город он принес.",0,278,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но как же ты меж ними уцелела?",0,279,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","У матери была я на руках.",0,280,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Что взят землей отец твой, тоже правда?",0,281,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Царя пучин трезубцем он убит…",0,282,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Там, где еще скала зовется Долгой?",0,283,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Что ты сказал?.. Тот звук напомнил мне…",0,284,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Что пламени Пифийцы скалы любы…",0,285,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Он любит их! Не знала я, зачем?",0,286,0,0],["sd","⟨<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Он любит — ты ж как будто ненавидишь?",0,287,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","На них пятно… Не спрашивай, мой друг⟩",0,288,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","после паузы"],["v","А муж твой кто? Афинянин, конечно?",0,289,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нет, он не наш, — он из другой страны.<a class=\"nr\" href=\"#n-k14\" data-n=\"k14\" aria-label=\"Примечание 14\">14</a>",0,290,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но кто? Должно быть, тоже благородный?",0,290,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Эолов сын, внук Зевса, имя — <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>.",0,291,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А как же ты досталась чужестранцу?",0,292,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Невдалеке Евбея от Афин…",0,293,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Окружена водой она, однако ж…",0,294,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Соединясь с Афинами, ее",0,295,0,0],["v","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> разорил копьем, Евбею эту…",0,296,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Им <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> помог и получил тебя?",0,297,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, я была наградою победной.",0,298,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А что ж, ты здесь одна или с царем?",0,299,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","С царем, да он к Трофонию заехал.<a class=\"nr\" href=\"#n-k15\" data-n=\"k15\" aria-label=\"Примечание 15\">15</a>",0,300,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Так, поглядеть, или гадает он?..",0,301,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","И здесь и там — все об одном гадает.",0,302,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Не всходит хлеб или ребенка нет?",0,303,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Бездетны мы… Который год женаты…",0,304,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ни разу ты еще не родила?..",0,305,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Бездетна я… То знает Аполлон.",0,306,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Всем счастлива, а в этом нет удачи…",0,307,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Но кто же ты? Твоя блаженна мать…",0,308,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Я — божий раб. Так и зовусь, царица…",0,309,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Дар города иль продан кем-нибудь?..",0,310,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Одно лишь знаю: раб я Аполлонов…",0,311,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Прими ж в ответ ты слезы и от нас.",0,312,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Как сирота безвестного рожденья…",0,313,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты тут живешь или имеешь дом?",0,314,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Где сон возьмет, там мне и дом, царица.",0,315,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Но с детства ты или недавно здесь?",0,316,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Едва увидев свет, как уверяют…",0,317,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","А кто ж кормил тебя?.. Ведь это ж храм.",0,318,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","показывает на закрытую дверь"],["v","О, груди я не знал… Вот та кормила…",0,319,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Кто? Бедный, кто? Несчастье нас роднит…",0,320,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Пророчицу я называл «родимой».",0,320,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Теперь ты муж. Но как ты вырастал?",0,321,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Алтарь питал, да гости нам дарили…",0,322,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, матери не сладко… Кто же мать?..",0,323,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Насилием, быть может, был я создан…",0,324,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Но, вижу я, ты хорошо одет.",0,325,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Господская одежда — божья риза…",0,326,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты отыскать не пробовал свой род?",0,327,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да где же след для розыска, царица?",0,328,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Увы! Увы!",0,329,0,0],["v","Я знаю мать с такою же судьбой.",0,330,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Кого? Делиться горем — утешает.",0,331,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Из-за нее и торопилась я",0,332,0,0],["v","Поспеть сюда, покуда царь не прибыл…",0,333,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Чего ж ей надо?.. Не могу ли я?",0,334,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Оракул ей, но тайный, нужен здесь…",0,335,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Доверься ж нам, — и мы устроим дело.",0,336,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["sd","Ну, слушай же… (Закрывает лицо руками.) Нет… стыдно говорить!"],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Так дело брось. Ведь Стыд — он бог ленивый…",0,337,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","не поднимая головы"],["v","Она была в объятьях Феба… О…",0,338,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Была его женой? Ни слова дальше!..",0,339,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Родился сын… Отец ее не знал…",0,340,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Не может быть! Ее обидел смертный,",0,340,0,0],["v","И стыдно ей — вот бога и винит.",0,341,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Клянется, что не смертный… Ужас, ужас…",0,342,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Где ж ужас, если бог ее избрал?",0,343,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Рожденного из дома удалила…",0,344,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И где же он? Еще ли видит свет?..",0,345,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","За этим-то оракул ей и нужен…",0,346,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но если ж нет его, погиб… то как?",0,347,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Догадка есть, что звери разорвали.",0,348,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","По признакам догадка создалась?",0,349,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","На месте том, где кинуто дитя,",0,350,0,1],["v","Когда пришла, его не оказалось…",0,350,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Оттуда шли кровавые следы?",0,351,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Вот то-то нет. Она следов искала…",0,352,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А как давно ребенка-то уж нет?",0,353,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","посмотрев на <span class=\"ch\" data-ch=\"ion\">Иона</span>"],["v","Он был бы твой ровесник, если б жил…",0,354,0,0],["sd","⟨<span class=\"ch\" data-ch=\"ion\">Ион</span>⟩"],["v","Да, бог ее обидел. Грустный жребий!",0,355,0,0],["sd","⟨<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>⟩"],["v","И после уж она не родила!",0,356,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А что, как Феб взрастил ребенка тайно?",0,357,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Присвоить радость общую грешно.",0,358,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Увы! Своей судьбы я слышу отзвук…",0,359,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","И по тебе, поди, тоскует мать…",0,360,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Нет, не зови к слезам, уже забытым.",0,361,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Молчу… К вопросу моему вернись…",0,362,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А знаешь, где больное место в деле?..",0,363,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Все для нее больное место, все…",0,364,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Коль бог таит, так для чего ж он скажет?",0,365,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Так для чего же ваш срединный храм?",0,366,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Стыда богов разоблачать не надо…",0,367,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Стыда богов? А ей был легок стыд?",0,368,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Для дел таких здесь помощи не сыщешь.",0,369,0,0],["v","А Феб, в своем же доме обличенный,",0,370,0,1],["v","Без кары бы профета не оставил<a class=\"nr\" href=\"#n-k16\" data-n=\"k16\" aria-label=\"Примечание 16\">16</a>",0,370,0,0],["v","И был бы прав. Ступай отсюда лучше…",0,371,0,0],["v","Гадать о том, что против бога… нет!",0,372,0,0],["v","Ведь этак ты вообразишь, пожалуй,",0,373,0,0],["v","Что вынудить, мы можем и богов,",0,374,0,0],["v","Наперекор их воле, открываться, —",0,375,0,0],["v","Овцу зарезать стоит или птиц",0,376,0,0],["v","На небе проследить… О нет, жена,",0,377,0,0],["v","Ничтожна та и польза, что добыта",0,378,0,0],["v","Насилием от бога, только то,",0,379,0,0],["v","Что волей их дано, благословенно…",0,380,0,1],["sp","Корифей"],["v","Над множеством людей и без числа<a class=\"nr\" href=\"#n-k17\" data-n=\"k17\" aria-label=\"Примечание 17\">17</a>",0,380,0,0],["v","Есть разных бед на свете. Но найдется ль",0,381,0,0],["v","Такой меж них, чтоб видел только счастье?",0,382,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Не прав ты, Феб, и там был, но и здесь",0,383,0,0],["v","Не прав пред той, которой нет, чьи речи",0,383,0,0],["v","Одни звучали здесь: не захотел",0,384,0,0],["v","Ты сохранить рожденного тобою —",0,385,0,0],["v","А не твое ли это дело было?..",0,386,0,0],["v","И матери его открыть не хочешь,",0,386,0,0],["v","Что сталось с ним, чтоб, если сына нет,",0,387,0,0],["v","Она его гробницею почтила,",0,388,0,0],["v","А если жив, нашла когда-нибудь.",0,389,0,0],["v","Да, кажется, гадать напрасно будет,",0,390,0,1],["v","Когда сам бог идет наперекор.",0,390,0,0],["v","Но вижу я блистающего родом",0,391,0,0],["v","Супруга своего; чертоги он",0,392,0,0],["v","Трофония покинул — (к <span class=\"ch\" data-ch=\"ion\">Иону</span>) перед <span class=\"ch\" data-ch=\"ksuf\">Ксуфом</span>",0,393,0,0],["v","О сказанном ни слова! — Не хочу",0,394,0,0],["v","Нести стыда за тайную услугу,",0,395,0,0],["v","Да и слова мои растолковать",0,396,0,0],["v","Совсем иначе могут, коль молва",0,397,0,0],["v","Пойдет об них. Легко ли женам с вами?",0,398,0,0],["v","Что добрая, что злая — все равно",0,399,0,0],["v","Мужчинам ненавистны. Злая доля!..",0,400,0,1],["scene","Явление пятое","s6",2,6],["v","Те же и <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> со свитой.",0,400,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","О, радуйся, дельфийский бог, тебе",0,401,0,0],["v","Начало слов моих.",0,402,0,0],["sd","(<span class=\"ch\" data-ch=\"kreusa\">Креусе</span>.)"],["v","Царица, здравствуй.",0,403,4,0],["v","Я думаю, ты заждалась меня.",0,403,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Заждалась — не скажу, но все ж заботой",0,404,0,0],["v","Ты мне наполнил сердце. Но скажи,",0,405,0,0],["v","Что нам вещал Трофоний? Наш союз",0,406,0,0],["v","Рождением детей благословится ль?",0,406,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Он вещих слов дельфийца не хотел",0,407,0,0],["v","Предупреждать. Но только мы отсюда,",0,408,0,0],["v","Ни ты, ни я, бездетны не уйдем…",0,409,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Богиня, матерь Феба! Наш приход",0,410,0,1],["v","Благослови и обрати во благо",0,411,0,0],["v","Меж нами и тобой рожденным встречу…",0,412,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["sd","О, верно, так и будет. (К <span class=\"ch\" data-ch=\"ion\">Иону</span>.) Где ж профет?"],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Я только здесь, в притворе. Есть другие,",0,413,0,0],["v","К треножнику они садятся, гость,",0,414,0,0],["v","Поближе нас. И этот цвет дельфийский",0,415,0,0],["v","По жребию сменяется у нас.",0,416,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Так, хорошо. Теперь я знаю все",0,417,0,0],["v","И в дом войти могу. Я слышал, нынче",0,418,0,0],["v","Как раз для всех пришедших перед храмом",0,419,0,0],["v","Даются пресказанья. Видно, бог",0,420,0,1],["v","Судил и мне оракулом сегодня<a class=\"nr\" href=\"#n-k18\" data-n=\"k18\" aria-label=\"Примечание 18\">18</a>",0,420,0,0],["v","Утешиться. Ты ж, женщина, алтарь",0,421,0,0],["v","Лавровыми ветвями обвивая,",0,422,0,0],["v","Молись, чтоб мы из храма принесли",0,423,0,0],["v","Счастливое пророчество о детях…",0,423,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да будет так!",0,424,0,0],["v","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> со свитой уходит в храм.",0,425,0,0],["v","Вот если бы теперь",0,426,4,0],["v","Свою вину загладил Феб! Загладить",0,426,1,0],["v","Ее вполне не может он, пускай —",0,427,1,0],["v","Отчасти хоть. От бога все приму я…",0,428,1,0],["sd","(Уходит со служанками в лавровую рощу.)"],["scene","Явление шестое","s7",2,7],["sd","Без <span class=\"ch\" data-ch=\"kreusa\">Креусы</span> и <span class=\"ch\" data-ch=\"ksuf\">Ксуфа</span>."],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","С какой бы стати этой чужестранке",0,429,0,0],["v","Своею темной речью обносить",0,430,0,1],["v","Дельфийского владыку?..",0,430,0,0],["sd","(Задумывается.)"],["v","Иль из дружбы",0,431,4,0],["v","К той женщине, которая гадать",0,432,0,0],["v","Ее просила? Или — чтоб словами",0,433,0,0],["v","Прикрылось то, чего сказать нельзя!",0,433,0,0],["sd","Пауза."],["v","Дочь Эрехтея… А какое дело",0,434,3,0],["v","Мне до нее, скажите? Лучше лейки",0,435,3,0],["v","Из золотых кувшинов наполняй!",0,436,3,0],["sd","(Принимается за работу, но потом останавливается.)"],["v","Я все-таки не понимаю Феба…",0,436,3,0],["v","Насиловать девиц, чтоб после бросить…",0,437,3,0],["v","А дети? Потихоньку сплавил их,",0,438,3,0],["v","И пусть их погибают. Что ему-то…",0,439,3,0],["v","Нехорошо… Могуч, — так будь и честен.",0,440,3,1],["v","Кто из людей преступит, ведь небось",0,440,3,0],["v","Того карают боги… Как же, нам",0,441,3,0],["v","Законы сочиняя, вы добьетесь,",0,442,3,0],["v","Чтоб их мы исполняли, если их",0,442,3,0],["v","Вы ж первые нарушить не боитесь?",0,443,3,0],["v","Да, если бы пришлось вам искупать",0,444,3,0],["v","Любовные грехи, — от слова ведь",0,445,3,0],["v","Не станется, но пусть, — то ты, владыка,",0,445,3,0],["v","Да Посейдон, да миродержец Зевс",0,446,3,0],["v","Сокровища из храмов расточили б.",0,447,3,0],["v","Без удержу спеша за наслажденьем,",0,447,3,0],["v","Забыли вы о правде. И клеймить",0,448,3,0],["v","Людей за их пороки не ошибка ль?..",0,449,3,0],["v","Коли богов пример перед людьми —",0,450,4,1],["v","Кто ж виноват? Учителя, пожалуй…",0,451,3,0],["scene","Первый музыкальный антракт","s8",2,8],["sp","Хор"],["str","Строфа"],["v","Мук рождением не давшей,",0,452,0,0],["v","Я тебе молюсь, Афина,",0,453,0,0],["v","Ты, которую когда-то",0,454,0,0],["v","Прометей-титан воспринял",0,455,0,0],["v","Из Кронидова чела!",0,456,0,0],["v","О блаженная Победа,<a class=\"nr\" href=\"#n-k19\" data-n=\"k19\" aria-label=\"Примечание 19\">19</a>",0,457,0,0],["v","Из златых дворцов Олимпа",0,458,0,0],["v","В дом пифийский снизойди,",0,460,0,1],["v","Где очаг средиземельный,",0,460,0,0],["v","Где с треножника, который",0,461,0,0],["v","Пляскою святой прославлен,",0,462,0,0],["v","Слово вещее слетает.",0,463,0,0],["v","Ты и дочь Латоны — обе",0,464,0,0],["v","Вы богини, обе девы,",0,465,0,0],["v","Феба царственные сестры,",0,466,0,0],["v","Помолитесь же, о девы,",0,467,0,0],["v","Чтобы древний Эрехтея",0,468,0,0],["v","Наконец венчался род",0,469,0,0],["v","В ясном слове Аполлона",0,470,0,1],["v","Обещанием детей.",0,471,0,0],["str","Антистрофа"],["v","Счастья высшего начала,",0,472,0,0],["v","Нерушимого для смертных,",0,473,0,0],["v","Нет иного, как в чертогах",0,474,0,0],["v","Детских глаз сиянье: радость",0,475,0,0],["v","Видеть нежный цвет детей,",0,476,0,0],["v","Чтоб, сокровища наследье",0,477,0,0],["v","От отцов приявши, дети",0,478,0,0],["v","Детям отдали своим.",0,480,0,1],["v","В бедах дети — это сила,",0,480,0,0],["v","Дети в счастии — улыбка,",0,481,0,0],["v","На войне они отчизне",0,482,0,0],["v","И опора и спасенье…",0,483,0,0],["v","Не давай ты мне богатства,",0,484,0,0],["v","Царских зал раззолоченных!",0,485,0,0],["v","Дай мне вырастить на славу,",0,486,0,0],["v","Дай взлелеять мной рожденных.",0,487,0,0],["v","Жизнь бездетных ненавистна:",0,488,0,0],["v","Этой жизни не желай;",0,489,0,0],["v","С самым скромным достояньем",0,490,0,1],["v","В детях счастье для меня.",0,491,0,0],["str","Эпод"],["v","Ты, о Пана жилище",0,492,0,0],["v","Близ пещеры глубокой!",0,493,0,0],["v","Там три дочери нежных",0,494,0,0],["v","Белоногих Аглавры",0,495,0,0],["v","На лугу танцевали",0,496,0,0],["v","Перед храмом Паллады.",0,497,0,0],["v","Ты же играл им, о Пан,",0,500,0,1],["v","Из вертепа, где дева,",0,500,0,0],["v","Сына Фебу родивши,",0,501,0,0],["v","— О, безумье несчастья! —",0,502,0,0],["v","Отдала этот стыд",0,502,0,0],["v","Рокового союза",0,503,0,0],["v","Клюву, пасти — ребенка.",0,504,0,0],["v","Много сказок у кросен,",0,505,0,0],["v","Много знаю вестей людских,",0,505,0,0],["v","Но такого не помню,",0,506,0,0],["v","Чтобы счастье венчало",0,507,0,0],["v","Порожденного девой",0,507,0,0],["v","От союза с бессмертным.",0,508,0,0],["act","Действие второе","a3","II"],["scene","Явление седьмое","s9",3,9],["v","<span class=\"ch\" data-ch=\"ion\">Ион</span> (из боковых дверей).",0,509,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А, царицыны рабыни! Вы все здесь у ступеней",0,510,0,1],["v","В облаках благоуханий дожидаетесь царя…",0,511,0,0],["v","Что ж, треножник им покинут? Предсказание дано?",0,512,0,0],["v","Или, все еще бездетен, бога <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> не умолил?",0,513,0,0],["sp","Корифей"],["v","Там покуда он, во храме; не сходил со ступеней.",0,514,0,0],["v","Только будто уж выходит: застучали ворота…",0,515,0,0],["v","Так и есть, — сейчас увидишь господина ты и сам.",0,516,0,0],["scene","Явление восьмое","s10",3,10],["sd","Из средних дверей выходит <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>. Он в венке и радостный. <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> и <span class=\"ch\" data-ch=\"ion\">Ион</span>."],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["dir","едва появляясь на сцену, видит <span class=\"ch\" data-ch=\"ion\">Иона</span> и поспешно направляется к нему, раскрыв объятия"],["v","Сын мой, радуйся! О сын мой! Да, я смею так начать…",0,517,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","слегка отстраняясь"],["v","Радость — нам, а <span class=\"ch\" data-ch=\"ksuf\">Ксуфу</span> — разум, и никто не обделен.",0,518,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["dir","с настойчивой горячностью"],["v","Руку дай мне — поцелуя и объятья я хочу.",0,519,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","раздражительнее"],["v","Да в уме ль ты, или душу бог безумьем повредил?",0,520,0,1],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Я в уме ль, когда находке я своей нежданной рад?",0,521,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","вырываясь"],["v","Перестань! Неосторожно ты венок мне изомнешь…",0,522,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Не отстану… Тут не дерзость… Ты любовью обретен.",0,523,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","берется за лук"],["v","Отойди, коли не хочешь задохнуться от стрелы.",0,524,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["dir","отходит"],["v","Ты бежишь меня! Но должен ты любить меня, пойми!",0,525,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","покачивая головой"],["v","Нет, невеж и одержимых не согласен я любить.",0,526,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Что ж? Убей, сожги, пожалуй, — скажут все: отца убил.",0,527,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","с живостью"],["v","Ты — отец мне? На смех, что ли, те слова, афинский царь?",0,528,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Дай свободно им излиться, — и тогда ты все поймешь.",0,529,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ну, и что же я услышу?",0,530,0,1],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Я — отец твой, ты — мой сын.",1,530,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Кто ж сказал тебе?",0,530,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Сам Локсий, твой кормилец, мне открыл.",1,530,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","насмешливо"],["v","Ты — истец, ты ж и свидетель…",0,531,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Да, но божьих слов, прибавь.",1,531,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Их загадкой ты обманут.",0,532,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Значит, бог не так сказал.",1,532,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Кто ж указан?",0,533,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Тот, кто первый мне навстречу попадет.",0,534,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Как, навстречу?",0,535,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Мне навстречу, чуть ступлю я за порог.",0,535,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ну! И что же… Этот встречный?",0,536,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Будет сыном мне родным.",1,536,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Настоящим иль приемным?..",0,537,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Хоть приемным, плоть — моя.",1,537,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты со мной столкнулся с первым?",0,538,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","С кем другим, мое дитя?",1,538,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но откуда ж этот случай?",0,539,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Ты дивишься не один.",1,539,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Хорошо, а мать-то кто же?",0,540,0,1],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Сам не знаю я, кто мать.",1,540,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Феб ее, однако, назвал?",0,541,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Не спросил я, так был рад.",1,541,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","усмехаясь"],["v","Видно, я рожден землею…",0,542,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Не родит земля детей.",1,542,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","От кого ж я твой?",0,543,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Не знаю, шлюсь на бога: бог сказал.",1,543,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Попытаем речь иную.",0,544,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Что ж, пожалуй, я не прочь.",1,544,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Знал ты женщин, кроме брака?",0,545,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Молод был — подчас знавал…",1,545,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Раньше брака с Эрехтидой?",0,546,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Да, уж после — ни одной.",1,546,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Значит, я родился раньше?",0,547,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","По годам бы подошло.",1,547,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но сюда-то как попал я?",0,548,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Сам придумать не могу.",1,548,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Путь не близкий…",0,549,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["dir","задумчиво"],["v","Да — задача: разберись-ка в ней поди.",1,549,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты бывал на этих скалах?",0,550,0,1],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Славя Вакховы огни.<a class=\"nr\" href=\"#n-k20\" data-n=\"k20\" aria-label=\"Примечание 20\">20</a>",1,550,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И гостил у друга в доме?",0,551,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","С ним ходил и в хоровод…",1,551,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","после минуты молчания"],["v","Ты в фиасе был, сказал ты?",0,552,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Да, на оргиях менад.",1,552,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты был скромен или… весел?",0,553,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Не без Вакха обошлось…",1,553,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Не тогда ль и был я зачат?..",0,554,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Будто вышло, что тогда…",1,554,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да, но я был найден в храме…",0,555,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","И подкинуть мать могла.",1,555,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Слава богу, хоть не раб я.",0,556,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Что ж? Отец ли я тебе?",1,556,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Видно, богу надо верить.",0,557,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Вразумился наконец!",1,557,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да, и жребий свой я славлю…",0,558,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Бог глаза тебе открыл.",1,558,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Зевсу внук я — славный жребий!<a class=\"nr\" href=\"#n-k21\" data-n=\"k21\" aria-label=\"Примечание 21\">21</a>",0,559,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Да, и он отныне твой.",1,559,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","открыв объятья, приближается к <span class=\"ch\" data-ch=\"ksuf\">Ксуфу</span>"],["v","Обниму ль отца?",0,560,0,1],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Обнимешь, если богу веришь ты.",0,560,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ну, отец мой, здравствуй!",0,561,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Сладко это слышать мне, дитя.",1,561,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Солнца этого сиянье…",0,562,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","…Над блаженным догорит.",1,562,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О родимая! С тобой же мы увидимся когда?",0,563,0,0],["v","Горячей желанье в сердце видеть милые черты.",0,564,0,0],["v","Иль тебя между живыми бесполезно и искать?",0,565,0,0],["sp","Корифей"],["v","Неразделимо счастие семьи…",0,566,0,0],["v","А все же если б и царице сына,",0,567,0,0],["v","Чтоб им процвел ее старинный дом…",0,568,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Дитя мое, устроил справедливо",0,569,0,0],["v","Свиданье наше бог, и ты отныне",0,570,0,1],["v","Со мною связан крепко. И печаль,",0,571,0,0],["v","Которой ты охвачен, справедлива.",0,572,0,0],["v","Я сам делю ее. Ну, бог пошлет,",0,573,0,0],["v","Узнаешь и о матери. Дай время:",0,574,0,0],["v","Еще и мать отыщем. А теперь",0,575,0,0],["v","Немедля храм покинь ты и скитальца",0,576,0,0],["v","Удел забудь, мой сын. Душой с отцом",0,577,0,0],["v","Сольешься ты. И вместе мы в Афины",0,578,0,0],["v","Отправимся — там роскошь и престол",0,579,0,0],["v","Отцовские, и там ничто недугов",0,580,0,1],["v","Безродности и нищеты тебе,",0,580,0,0],["v","Конечно, не напомнит. Вспомни только,",0,581,0,0],["v","Что ты и благороден и богат.",0,582,0,0],["v","Но ты молчишь? Лицо к земле ты клонишь?",0,583,0,0],["v","К заботам ты вернулся… Иль отцу",0,584,0,0],["v","Ты отравить тревогой радость хочешь?..",0,585,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","который стоял во время слов отца в печальном раздумье, теперь поднимает голову и начинает тихо, лишь мало-помалу оживляясь"],["v","Различен вид вещей, — глядишь ли их",0,585,0,0],["v","Ты издали иль подойдешь, чтоб видеть.",0,586,0,0],["v","Судьбу свою приветствую — отца",0,587,0,0],["v","Я приобрел. Но слушай, что приходит",0,588,0,0],["v","Мне в голову: афинский род исконный,",0,589,0,0],["v","Не пришлый род, и славен город ваш.",0,590,0,1],["v","А я войду в Афины и с собою",0,590,0,0],["v","Два приведу недуга — ты пришлец,",0,591,0,0],["v","Да я еще, твой незаконный сын.",0,592,0,0],["v","Укоры и бессилье мне стяжают",0,593,0,0],["v","Два прозвища: Ничто и Из ничьих.",0,593,0,0],["v","А меж гребцов явившись первым, если",0,594,0,0],["v","Я захочу и значить что-нибудь, —",0,595,0,0],["v","Вот ненависть бессильных и готова.",0,596,0,0],["v","Ведь власть всегда обидна. Ну, а лучшим",0,596,0,0],["v","И сильным, если эти люди только",0,597,0,0],["v","Спокойствие свое предпочитают",0,598,0,0],["v","Ораторским успехам и в дела",0,599,0,0],["v","Не мечутся, глупцом я покажуся.",0,600,0,1],["v","\"И он туда ж, как будто бы у нас",0,600,0,0],["v","И без него не вдоволь было шуму\".",0,601,0,0],["v","И черепки влиятельных мужей,<a class=\"nr\" href=\"#n-k22\" data-n=\"k22\" aria-label=\"Примечание 22\">22</a>",0,602,0,0],["v","Политиков афинских? Или сану",0,603,0,0],["v","Высокому грозить они не будут?..",0,604,0,0],["v","Ведь так везде бывает: в городах",0,605,0,0],["v","Добившийся успеха не выносит",0,605,0,0],["v","Соперника…",0,606,0,0],["v","Ну, а в палатах царских,",1,606,0,0],["v","Где я глаза жене твоей бы стал,",0,607,0,0],["v","Незваный гость, мозолить? Не с тобой ли",0,608,0,0],["v","Она делила горе, а теперь",0,609,0,0],["v","Все бремя ей ты отдал бы. Послушай:",0,610,1,1],["v","Да разве же возможно было б ей",0,610,0,0],["v","Меня не ненавидеть, постоянно",0,611,0,0],["v","Терзаясь нашей близостью, когда",0,612,0,0],["v","Она — жена бездетная, и только?..",0,613,0,0],["v","Тебе, отец, на выбор: иль меня",0,614,0,0],["v","Жене твоей предать в угоду, или",0,615,0,0],["v","Наполнить смутой дом. Да не забудь,",0,615,0,0],["v","Что и у жен про вас еще бывает",0,616,0,0],["v","И нож и яд, когда на то пошло.",0,617,0,0],["v","Но мне, отец, твоей царицы жаль,",0,618,0,0],["v","Что без детей стареет, благородных",0,619,0,0],["v","Корней побег, а не дает плода…",0,620,0,1],["v","Ты хвалишь царский жребий.",0,620,0,0],["v","Точно, с виду",1,620,0,0],["v","Отраден он, но глубже загляни:",0,621,0,0],["v","Там каково? О, счастье! О, блаженство!",0,622,0,0],["v","Век трепетать насилья, озираясь,",0,623,0,0],["v","Не свило ли поблизости гнезда,",0,623,0,0],["v","Безвестное, но счастье! — а тираном",0,624,0,0],["v","Я быть не льщусь.",0,625,0,0],["v","Он рад, коль залучит",1,625,0,0],["v","В друзья себе злодеев. Всякий честный",0,626,0,0],["v","Тирану — острый нож. Трепещет он",0,626,0,0],["v","В нем своего убийцы. Скажешь: деньги",0,627,0,0],["v","Вознаградят за все — в обилье сладость.",0,628,0,0],["v","Нет, не люблю проклятий возбуждать,",0,629,0,0],["v","Над сундуками сидя; мне тревоги",0,630,0,1],["v","Богатых ненавистны. Я беспечной",0,630,0,0],["v","Хочу и скромной жизни.",0,631,0,0],["v","Здесь, отец,",1,631,0,0],["v","Кой-чем и мы владеем: нет приятней",0,632,0,0],["v","Досуга человеку, а у нас",0,633,0,0],["v","Найдется и досуг: хлопот немного.",0,634,0,0],["v","С пути меня никто, злодей, не сбросит,",0,635,0,0],["v","И уступать тому, кто ниже нас,",0,636,0,0],["v","Дороги я не должен, что несносно.",0,637,0,0],["v","Молюсь богам, беседую с людьми",0,638,0,0],["v","И радостным служу, а не печальным.",0,639,0,0],["v","Одних проводишь — новые идут,",0,640,0,1],["v","Не надоешь ты людям, и они,",0,640,0,0],["v","Сменяясь, интересней.",0,641,0,0],["v","Чт<em>о</em> мы даже",1,641,0,0],["v","И против воли ценим — справедливость, —",0,642,0,0],["v","Законом и природою зараз",0,643,0,0],["v","Мне привита во славу бога. Это",0,644,0,0],["v","Соображая все, я нахожу,",0,645,0,0],["v","Что здешняя афинской жизни лучше.",0,645,0,0],["v","Оставь меня при храме: все равно,",0,646,0,0],["v","Великим ли иль малым кто доволен…",0,647,0,0],["sp","Корифей"],["v","Ты хорошо сказал; моим друзьям",0,648,0,0],["v","От слов твоих пускай бы — только счастье.",0,649,0,0],["sp","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>"],["v","Довольно слов! Учись счастливым быть.",0,650,0,1],["v","А для начала я на месте встречи",0,650,0,0],["v","Устрою пир для всех, и мы за стол",0,651,0,0],["v","С тобою сядем — шутка! — день рожденья,",0,652,0,0],["v","И до сих пор он жертвой не почтен.",0,653,0,0],["v","В Афины ты поедешь, но как гость,",0,653,0,0],["v","Там ублажу тебя пирами, город",0,654,0,0],["v","Осматривать ты будешь, сыном я",0,655,0,0],["v","Не назову тебя еще. Царицу",0,656,0,0],["v","Бездетную мне счастьем огорчать",0,656,0,0],["v","Своим бы не хотелось.",0,657,0,0],["v","Будет время,",1,657,0,0],["v","Когда, со мной согласная, сама",0,658,0,0],["v","Тебе вручит она права на царство.",0,659,0,0],["v","Ион, сиречь, <em>Идущий</em> — вот тебе<a class=\"nr\" href=\"#n-k23\" data-n=\"k23\" aria-label=\"Примечание 23\">23</a>",0,660,0,1],["v","И имя, сын. Следы связал с моими",0,661,0,0],["v","Ты первый, как из храма выходил я;",0,662,0,0],["v","Ступай же, созови друзей на пир:",0,663,0,0],["v","Отвальная с богатой жертвой будет…",0,664,0,0],["v","А вам, рабыни, цепи на уста!<a class=\"nr\" href=\"#n-k24\" data-n=\"k24\" aria-label=\"Примечание 24\">24</a>",0,665,0,0],["v","Коли жене хоть слово — ждите казни.",0,666,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Идти — пойду. Но счастья в сердце нет.",0,667,0,0],["v","Коль не найду родимой, царь-отец,",0,668,0,0],["v","Мне жизнь не в жизнь.",0,670,0,1],["v","Добавлю пожеланье,",1,670,0,0],["v","Чтоб род ее афинский был, — тогда,",0,670,0,0],["v","Хоть с женской стороны, но мой язык",0,671,0,0],["v","Свободен, а не то среди народа",0,672,0,0],["v","Без подмеси, будь даже гражданин,",0,673,0,0],["v","Но гость, ты — раб и говорить не смеешь.",0,674,0,0],["sd","Оба уходят."],["scene","Второй музыкальный антракт","s11",3,11],["sp","Хор"],["str","Строфа"],["v","Я слезы вижу, я внемлю<a class=\"nr\" href=\"#n-k25\" data-n=\"k25\" aria-label=\"Примечание 25\">25</a>",0,675,0,0],["v","Скорбному воплю, и стоны,",0,676,0,0],["v","Стоны прорвались. Царица",0,677,0,0],["v","Узнала, что мужу",0,678,0,0],["v","Счастье отца открылось,",0,679,0,0],["v","А ей оставаться бездетной…",0,680,0,1],["v","О сын Латоны, о вещий!",0,681,0,0],["v","Что значит твое предсказанье?",0,682,0,0],["v","Откуда он, этот питомец",0,683,0,0],["v","Алтарный, и кто его мать?",0,684,0,0],["v","Я мучусь сомненьем:",0,685,0,0],["v","Коварства тут нет ли какого?",0,686,0,0],["v","Судьбы трепещу я,",0,687,0,0],["v","Куда повернется судьба?",0,688,0,0],["v","Понять не могу откровенья,",0,689,0,0],["v","Мне страшны слова",0,690,0,1],["v","И сын этот чуждой крови,",0,690,0,0],["v","Что в дом наш наследником входит…",0,691,0,0],["v","Во всем этом кто же обмана,",0,692,0,0],["v","Как я, не почувствует, сестры?",0,693,0,0],["str","Антистрофа"],["v","Подруги! Нашей царице,",0,693,0,0],["v","Может быть, лучше скажем…",0,694,0,0],["v","Все ей откроем про мужа,",0,695,0,0],["v","С которым надежды",0,696,0,0],["v","Долго она делила",0,696,0,0],["v","И жребий слила, на горе.",0,697,0,0],["v","Он-то теперь с удачей,",0,698,0,0],["v","А ей суждены только беды:",0,699,0,0],["v","До старости белой без сына",0,700,0,1],["v","И жить без друзей суждено ей…",0,701,0,0],["v","О жалкий! богатства",0,702,0,0],["v","И дома чужого — все мало…",0,703,0,0],["v","Да сгибнет! Да сгибнет!",0,704,0,0],["v","Он предал мою госпожу.",0,705,0,0],["v","Из рук его богу отрадной",0,706,0,0],["v","Огонь не спалит",0,707,0,0],["v","Пусть жертвы ни разу, ни разу.",0,708,0,0],["v","Царица ж узнает, что близок",0,710,0,1],["v","Тот пир, где, еще непривычны",0,710,0,0],["v","Друг к другу, царь с сыном садятся.",0,711,0,0],["str","Эпод"],["v","О вы, парнасские скалы!",0,712,0,0],["v","Ты, утес, где тучи лежат,",0,713,0,0],["v","Где Вакх, воздымая горящую ель,",0,714,0,0],["v","С менадами в беге крылатом",0,715,0,0],["v","Делит влажную ночь, —",0,716,0,0],["v","Я вас призываю.",0,717,0,0],["v","Да в город ко мне не войдет",0,718,0,0],["v","Тот юный! Скорее его",0,719,0,0],["v","Пусть дни молодые прервутся…",0,720,0,1],["v","Стеная, наплыв чужестранный",0,721,0,0],["v","Наш город бы встретил…",0,722,0,0],["v","И тех не довольно ли с нас",0,723,0,0],["v","Гостей Эрехтея?..<a class=\"nr\" href=\"#n-k26\" data-n=\"k26\" aria-label=\"Примечание 26\">26</a>",0,724,0,0],["act","Действие третье","a4","III"],["scene","Явление девятое","s12",4,12],["sd","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> и старик (дядька) идут со стороны лавровой рощи. Старик весь белый, с палкой. <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> идет возле и по временам его поддерживает."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О старец — пестун моего отца,",0,725,0,0],["v","Когда он солнце видел, Эрехтея,",0,726,0,0],["v","Взбирайся к дому Вещего, — со мной",0,727,0,0],["v","Ты радость здесь разделишь, если бог",0,728,0,0],["v","Мне обещает счастье материнства…",0,729,0,0],["v","Счастливой быть при друге — в этом есть",0,730,0,1],["v","Особая отрада, а постигни",0,730,0,0],["v","Нас — боже сохрани — теперь беда,",0,731,0,0],["v","Что слаще сердцу ласкового взора?",0,732,0,0],["v","Как ты отца когда-то чтил, тебя",0,733,0,0],["v","Я чту, старик, хотя и заменила",0,734,0,0],["v","Покойного владыку твоего…",0,735,0,0],["sp","Старик"],["v","Родителей достойных дочь, — их славу",0,735,0,0],["v","Хранишь ты, о царица! Ты своих",0,736,0,0],["v","Не посрамила предков земнородных.",0,737,0,0],["v","Веди, веди меня к оракулу, но путь",0,738,0,0],["v","Туда тяжел — моим ногам дрожащим",0,739,0,0],["v","Поддержкой будь, а дряхлости — врачом.",0,740,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","За мной, старик, гляди, куда ступаешь.",0,740,0,0],["sp","Старик"],["v","Вот-вот…",0,741,0,0],["v","Эх, ноги еле-еле, ум — стрелой.",0,742,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Где поворот, на палку опирайся.",0,743,0,0],["sp","Старик"],["dir","ощупывая путь посохом"],["v","И посох слеп, когда не видит глаз.",0,744,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Бодрись, старик, бодрись, насколько можешь.",0,745,0,0],["sp","Старик"],["v","И рад бы был, да сил-то где возьмешь?",0,745,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","к хору"],["v","О женщины, у челнока и стана",0,746,0,0],["v","Надежные подруги! Что сказал",0,747,0,0],["v","Царю о детях Феб? Сюда за этим",0,748,0,0],["v","Спешили мы. Скорей же говорите,",0,749,0,0],["v","И если весть удачна ваша, в нас",0,750,0,1],["v","Вы не обманетесь — награда будет.",0,751,0,0],["sp","Корифей"],["v","О боже!",0,752,0,0],["sp","Старик"],["v","Хорошего начало не сулит.",0,753,0,0],["sp","Корифей"],["v","Ой, лихо!",0,754,0,0],["sp","Старик"],["v","Иль злая весть царю возвещена?",0,755,0,0],["sp","Корифей"],["v","Что делать? Мы ведь на волос от смерти.",0,756,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Что значит эта песня?.. Страх о чем?..",0,757,0,0],["sp","Корифей"],["v","Скажу или смолчу? О, что мне делать?",0,758,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Несчастье затаила ты — скажи!",0,759,0,0],["sp","Корифей"],["v","Да будет так — и пусть две казни после.",0,760,0,1],["v","Нет, не дано тебе детей, царица,",0,761,0,0],["v","Лелеять и к груди их прижимать.",0,762,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О, умереть…",0,763,0,0],["sp","Старик"],["sd","Дитя!.."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Как я несчастна!..",1,763,0,0],["v","Увы мне, увы! С мукой такою",0,764,0,0],["v","Будет не жизнь, подруги…",0,765,0,0],["v","Нет меня больше…",0,766,0,0],["sp","Старик"],["v","О дочь!",1,766,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ой, не могу!",1,766,0,0],["v","Мука пронзила мне сердце… Вот здесь…",0,767,0,0],["sp","Старик"],["v","Плакать успеешь.",0,768,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Тут ли не плакать?",1,768,0,0],["sp","Старик"],["v","Раньше узнаем…",0,770,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Что узнавать-то?",1,770,0,0],["sp","Старик"],["v","Участвует ли царь в твоей судьбе,",0,771,0,0],["v","Иль ты одна обречена несчастью?",0,772,0,0],["sp","Корифей"],["v","Ему, старик, бог сына даровал.",0,773,0,0],["v","Но без жены — один он счастлив сыном.",0,774,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Это уж слишком. Что ты сказала?",0,775,0,0],["v","Что ты сказала? Стоны теснятся…",0,776,0,0],["sp","Старик"],["v","Родится сын от женщины другой,",0,777,0,0],["v","Иль он уж есть? Как указал оракул?",0,778,0,0],["sp","Корифей"],["v","Нет, настоящий сын царю вручен:",0,780,0,1],["v","Здесь видела и дар я этот божий.",0,781,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Что ты вымолвить… что произнесть…",0,782,0,0],["v","Как ты дерзнула мне?",0,783,0,0],["sp","Старик"],["v","Дивлюсь и я… Какой бы мог оракул",0,784,0,0],["v","Исполниться сейчас же, не пойму.",0,785,0,0],["sp","Корифей"],["v","При выходе из храма кто бы первый",0,786,0,0],["v","С царем ни повстречался — тот и сын…",0,787,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Боже мой, боже мой!",0,788,0,0],["v","Радость… радость ребенка… где ж она?",0,789,0,0],["v","Пусто, как вымерло,",0,790,0,1],["v","В доме теперь навек.",0,791,0,0],["sp","Старик"],["v","А кто же повстречался? С кем же царь-то",0,792,0,0],["v","Следы смешал? И как? И где смешал?",0,793,0,0],["sp","Корифей"],["v","Подростка здесь, царица, ты видала, —",0,794,0,0],["v","Он мел притвор, — вот это сын и есть.",0,795,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Тучи, возьмите меня… с полей Эллады",0,796,0,0],["v","Далеко, в темную ночь,",0,797,0,0],["v","К мерцающим звездам.",0,798,0,0],["v","Сердце не вынесет муки.",0,799,0,0],["sp","Старик"],["v","По имени-то как назвал отец?",0,800,0,1],["v","Ты слышала? Иль имя неизвестно?",0,800,0,0],["sp","Корифей"],["v","<em><span class=\"ch\" data-ch=\"ion\">Ионом</span></em> — потому что <em>вышел</em> он.",0,801,0,0],["v","А матери его никто не знает.",0,802,0,0],["v","А чтобы все уж рассказать тебе.",0,803,0,0],["v","Что знаю я, так царь рожденье жертвой",0,804,0,0],["v","Отпраздновать украдкой от жены",0,805,0,0],["v","В священные палаты отбыл. С сыном",0,806,0,0],["v","Своим новоявленным пировать.",0,807,0,0],["sp","Старик"],["v","О госпожа! Мы преданы. С тобой",0,808,0,0],["v","И я. А царь над нами надругался…",0,809,0,0],["v","Афинский дом отныне нам закрыт…",0,810,0,1],["v","Так говорю не из слепой вражды",0,810,0,0],["v","К царю я, а затем лишь, что, конечно,",0,811,0,0],["v","Ты ближе мне, чем пришлый муж.",0,812,0,0],["v","Он в дом",1,812,0,0],["v","К тебе вошел, женившись, чтоб удел твой",0,813,0,0],["v","Забрать, — и вот у женщины другой",0,814,0,0],["v","Плод тайно сорванный теперь глазам открылся.",0,815,0,0],["v","Я объясню тебе и весь секрет.",0,816,0,0],["v","Когда увидел он, что ты бесплодна,",0,817,0,0],["v","Твоей судьбы делить не пожелав,",0,818,0,0],["v","К какой-нибудь рабыне он на ложе",0,819,0,0],["v","Украдкою вошел — и сын готов.",0,820,0,1],["v","К приятелю-дельфийцу он дитя",0,820,0,0],["v","Тогда сплавляет тайно, и у Феба,",0,821,0,0],["v","Чтоб отвести глаза, воспитан сын…",0,822,0,0],["v","И вот в Афины весть к царю доходит,",0,823,0,0],["v","Что сын его уж взрослый. Без труда",0,823,0,0],["v","Тебя тогда склонил он ехать к Фебу",0,824,0,0],["v","Детей просить.",0,825,0,0],["v","Оракул не солгал,",1,825,0,0],["v","Лишь царь тебя обманывал, давно уж",0,826,0,0],["v","Воспитывая сына, — чисто сплел…",0,826,0,0],["v","Чуть попадись, и вся вина на боге,",0,827,0,0],["v","А смотришь — время-то следы и замело,",0,828,0,0],["v","И <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> отдаст престол в наследье сыну.",0,829,0,0],["v","И имя-то придумал на досуге:",0,830,0,1],["v","<em><span class=\"ch\" data-ch=\"ion\">Ион</span></em> — мол, он ко мне навстречу шел.",0,830,0,0],["sp","Корифей"],["v","О, как я ненавижу кознодеев:",0,831,0,0],["v","Всегда они замышленное зло",0,832,0,0],["v","Узорами распишут — лучше друг",0,833,0,0],["v","Простой, но честный, чем хитрей, да низкий.",0,834,0,0],["sp","Старик"],["v","И худшее из зол, что в дом войдет",0,835,0,0],["v","Хозяином ничтожество, рабыней",0,836,0,0],["v","Рожденное. Уж, право, было б лучше",0,837,0,0],["v","Чтоб царь тебе наследника привел",0,838,0,0],["v","Из царского же рода, с твоего",0,839,0,0],["v","Согласия, затем что ты бездетна.",0,840,0,1],["v","Обидно бы — да что же делать? <span class=\"ch\" data-ch=\"ksuf\">Ксуф</span>",0,841,0,0],["v","Жениться все б в роду Эола должен…",0,842,0,0],["v","Теперь же, дочь моя, тебе за меч",0,843,0,0],["v","Иль яд, а взяться надо, — и коварством",0,844,0,0],["v","Прикончить вместе с <span class=\"ch\" data-ch=\"ksuf\">Ксуфом</span> и его",0,845,0,0],["v","Отродье, а не то тебя, гляди,",0,846,0,0],["v","Они убьют. Коль под одною кровлей",0,847,0,0],["v","Поселят двух врагов, так кто-нибудь",0,848,0,0],["v","Один погибнуть должен. Потружуся",0,849,0,0],["v","И я с тобой — мне сына предоставь:",0,850,0,1],["v","На пир их проберусь я. Лечь убитым",0,851,0,0],["v","Или на свет глядеть, — но раньше долг",0,852,0,0],["v","Я уплатить хочу своей царице",0,853,0,0],["v","За то, что нас питала. У раба",0,854,0,0],["v","Позорно только имя. Если честен,",0,855,0,0],["v","Так чем же он свободным не чета?",0,856,0,0],["sp","Корифей"],["v","И я хочу с тобою разделить",0,857,0,0],["v","И счастие, и смерть — с тобой, царица!",0,858,0,0],["v","О сердце! Как дольше молчать?..",0,859,1,0],["v","Позор ли осветишь?.. Но стыд?",0,860,1,1],["v","Помеха ль какая еще,",0,861,1,0],["v","Иль в доблести с кем состязаюсь?",0,862,1,0],["v","Не мужем ли я предана…",0,863,1,0],["v","Надежды! где они? Я не могла",0,864,0,0],["v","Осуществить желаний, даром только",0,865,0,0],["v","Таила брак — рождение таила,",0,866,0,0],["v","Слез полное… Довольно!..",0,867,0,0],["v","Я Зевса троном многозвездным,",0,870,1,1],["v","Богиней на холмах родимых",0,870,1,0],["v","Клянусь, священным побережьем,",0,871,1,0],["v","Волной беспокойной Тритонского моря.<a class=\"nr\" href=\"#n-k28\" data-n=\"k28\" aria-label=\"Примечание 28\">28</a>",0,872,1,0],["v","Скрывать я дольше не буду,",0,873,1,0],["v","Чьей жертвой была я…",0,874,1,0],["v","В груди из-под ига рождаясь,",0,875,1,0],["v","Уж слезы пробились и жгут",0,875,1,0],["v","Ланиты, и мечется сердце",0,876,1,0],["v","Меж козней богов",0,877,1,0],["v","И козней людских…",0,878,1,0],["v","Но я покажу, как и боги и люди",0,879,1,0],["v","Изменою брачное ложе покрыли.",0,880,1,1],["str","Строфа I"],["v","Тебе при солнечном свете",0,881,0,0],["v","О сын Латои, тебе",0,882,0,0],["v","Упреки, о нежный певец!",0,883,0,0],["v","С твоей семиструнною лирой,",0,884,0,0],["v","Где рога бездушье стонет<a class=\"nr\" href=\"#n-k29\" data-n=\"k29\" aria-label=\"Примечание 29\">29</a>",0,885,0,0],["v","Вслед за звонами гимна…",0,886,0,0],["str","Строфа II"],["v","В сиянье волос золотистых",0,887,0,0],["v","Ты ко мне подошел, когда",0,888,0,0],["v","Я цветы золотые в подол,",0,890,0,1],["v","Обрывая, сбирала и грудь",0,890,0,0],["v","Мне они щекотали…",0,891,0,0],["v","Стан мой белые руки обвили твои,",0,892,0,0],["v","И звала я: «О мать моя, мать!»",0,893,0,0],["v","Но в пещеру меня ты увлек",0,894,0,0],["v","И позором на радость Киприде покрыл…",0,895,0,0],["v","Я дала тебе сына, несчастная мать…",0,896,0,0],["v","Но из страха родимой в вертепе,",0,897,0,0],["v","Где я ложе с тобою делила,",0,898,0,0],["v","Где связал, ненавистный,",0,899,0,0],["v","Ты меня ненавистным ярмом,<a class=\"nr\" href=\"#n-k30\" data-n=\"k30\" aria-label=\"Примечание 30\">30</a>",0,900,0,1],["v","Был ребенок покинут, увы!..",0,901,0,0],["v","Где теперь он? Кровавые клювы",0,902,0,0],["v","Растащили его на пиру…",0,903,0,0],["v","Это сын твой. А ты, бездушный,",0,904,0,0],["v","На кифаре слагаешь так нежно",0,905,0,0],["v","Нам в усладу пэаны…",0,906,0,0],["v","Оге!..",0,907,0,0],["str","Строфа III"],["v","Сын Латои, тебе моя речь!<a class=\"nr\" href=\"#n-k31\" data-n=\"k31\" aria-label=\"Примечание 31\">31</a>",0,908,0,0],["v","Твой треножник средину земли",0,909,0,0],["v","Покрывает, из золота слит.",0,910,0,1],["v","И оттуда по жребию нам",0,910,0,0],["v","Ты, вещая, роняешь слова…",0,911,0,0],["v","Пусть мой голос в ушах у тебя",0,912,0,0],["v","Отдается, о низкий любовник!",0,913,0,0],["v","Ты у мужа не брал ничего",0,914,0,0],["v","И даешь ему сына в чертог…",0,915,0,0],["v","А твой сын, моя плоть, где он, где?",0,915,0,0],["v","Он расхищен пернатыми в поле",0,916,0,0],["v","Из моих материнских пеленок…",0,917,0,0],["v","Ненавидит, о Феб, тебя Делос,<a class=\"nr\" href=\"#n-k32\" data-n=\"k32\" aria-label=\"Примечание 32\">32</a>",0,918,0,0],["v","Зелень лавра тебя ненавидит,",0,919,0,0],["v","С нежнолистою пальмой свиваясь,",0,920,0,1],["v","Где тобою, плодом Дня",0,920,0,0],["v","Славным, ложе Латои сияло…",0,921,0,0],["sp","Корифей"],["v","Сокровища несчастий! Сколько их,<a class=\"nr\" href=\"#n-k27\" data-n=\"k27\" aria-label=\"Примечание 27\">27</a>",0,922,0,0],["v","И все они открылись… Слез-то, слез-то!",0,923,0,0],["sp","Старик"],["v","О дочь, в лицо твое не нагляжусь",0,924,0,0],["v","И плача полно сердце… Вне себя я…",0,925,0,0],["v","Я вычерпал волну беды, и вот",0,926,0,0],["v","Меня с кормы вторая поднимает…",0,927,0,0],["v","От слов твоих. Едва я принял груз",0,928,0,0],["v","Несчастий настоящих, уж для новых",0,929,0,0],["v","Ты открываешь гавань… Что сказать",0,930,0,1],["v","Решилась ты? В чем обвиняешь Феба?",0,931,0,0],["v","О сыне-то каком ты говоришь,",0,932,0,0],["v","Что будто родила, и где ж он брошен",0,933,0,0],["v","Зверям для погребенья? Объясни.",0,934,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Мне стыдно, но не потаю я, старец.",0,935,0,0],["sp","Старик"],["v","А я тебя сумею поддержать.",0,936,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Кекроповы тебе известны ль скалы?",0,937,0,0],["sp","Старик"],["v","Где Пан алтарь имеет? Знаю их.",0,938,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ужасный там свершился поединок.",0,939,0,0],["sp","Старик"],["v","Какой? Готовы слезы на ответ.",0,940,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Плачевный брак мой и насильный с Фебом.",0,941,0,0],["sp","Старик"],["v","Предчувствовал, скажи мне, не его ль?",0,942,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Не знаю. Коль его — ты не ошибся.",0,943,0,0],["sp","Старик"],["v","Украдкой стон недуг твой выдавал.",0,944,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, это было то, о чем ты слышишь.",0,945,0,0],["sp","Старик"],["v","Но как же брак могла ты утаить?",0,946,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я родила. Прими слова с терпеньем.",0,947,0,0],["sp","Старик"],["v","Где ж и при ком? Иль мучилась одна?",0,948,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Одна — и там, где сочеталась с богом.",0,949,0,0],["sp","Старик"],["v","Где ж сын?.. С тех пор уж не бездетна ты…",0,950,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Пропал. Зверям мой мальчик брошен, старец.",0,950,0,0],["sp","Старик"],["v","Пропал? А Феб? Иль, низкий, не помог?",0,951,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нет, не помог. Сын вырос в преисподней.",0,952,0,0],["sp","Старик"],["v","Но кто ж дитя-то бросил… Ведь не ты ж?",0,953,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я, в темноте завив его в мой пеплос.",0,954,0,0],["sp","Старик"],["v","И ни одна душа не знала, дочь?",0,955,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Никто, старик. Несчастие и тайна.",0,956,0,0],["sp","Старик"],["v","Как из пещеры ты могла уйти?",0,957,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Как? Жалобы твердя и плача горько.",0,958,0,0],["sp","Старик"],["v","Увы!",0,959,0,0],["v","Преступна ты была, преступней — бог…",0,960,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","прикрывая рукой глаза"],["v","Когда б ты видел: он ко мне тянулся…",0,961,0,0],["sp","Старик"],["v","Он грудь искал иль на руки хотел?",0,962,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Он грудь искал, где не был мной отвергнут…",0,963,0,0],["sp","Старик"],["v","Как вздумалось тебе расстаться с ним?",0,964,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я думала, что бог спасет малютку.",0,965,0,0],["sp","Старик"],["v","О, на тебя какая буря зол!",0,966,0,0],["sd","(Закрывается накидкой.)"],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Старик, зачем покрылся ты и плачешь?",0,967,0,0],["sp","Старик"],["v","Отца и дочь злосчастных вижу я.",0,968,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Таков удел людей. Ничто не прочно.",0,969,0,0],["sp","Старик"],["dir","открываясь"],["v","А все ж, дитя, мы плакать подождем.",0,970,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Но делать нам, что делать, я не вижу.",0,971,0,0],["sp","Старик"],["v","Твой первый был обидчик бог — плати…",0,972,0,0],["sd","Пауза."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Где ж силы взять мне, смертной, против бога?",0,973,0,0],["sp","Старик"],["v","Святилище Гадателя спали.",0,974,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Боюсь, и то не через край ли бедствий…",0,975,0,0],["sp","Старик"],["v","Тогда дерзни по силам, жертва — муж.",0,976,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","За прошлое мне свято ложе <span class=\"ch\" data-ch=\"ksuf\">Ксуфа</span>.",0,977,0,0],["sp","Старик"],["v","Ну что ж. Тогда ребенка… Тоже враг.",0,978,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Убить… Но как? Удастся ль? Я б желала.",0,979,0,0],["sp","Старик"],["v","Мечи раздай охранникам своим.",0,980,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да хоть сейчас. Но где ж расправа будет?",0,981,0,0],["sp","Старик"],["v","Друзей в шатре священном он поит.",0,982,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Убийства-то не скроешь… Раб не струсит?",0,983,0,0],["sp","Старик"],["v","Эх, дух твой слаб! Придумывай сама…",0,984,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","тихо"],["v","Я знаю способ тайный и надежный.",0,985,0,0],["sp","Старик"],["v","Тогда вдвойне и мной располагай.",0,986,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Слыхал ли ты о бое Землеродных?",0,987,0,0],["sp","Старик"],["v","Как на богов гиганты в Флегре шли…<a class=\"nr\" href=\"#n-k33\" data-n=\"k33\" aria-label=\"Примечание 33\">33</a>",0,988,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Там родила Земля Горгоны ужас.",0,989,0,0],["sp","Старик"],["v","Чтобы богам пришлося потрудней.<a class=\"nr\" href=\"#n-k34\" data-n=\"k34\" aria-label=\"Примечание 34\">34</a>",0,990,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, но и с ней покончила Паллада.",0,991,0,0],["sp","Старик"],["v","А чем же вид Горгоны так страшил?",0,992,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Вся грудь ее ехиднами клубилась.",0,993,0,0],["sp","Старик"],["v","Не эту ли я сказку и слыхал?",0,994,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Покров змеи украсил грудь Паллады.",0,995,0,0],["sp","Старик"],["v","Еще его Эгидою зовут…",0,996,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, <em>прянула</em> в сражение Горгона…<a class=\"nr\" href=\"#n-k35\" data-n=\"k35\" aria-label=\"Примечание 35\">35</a>",0,997,0,0],["sp","Старик"],["v","Но наш-то враг при чем тут, не пойму.",0,998,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты ж не слыхать не мог про Эрихтона…",0,999,0,0],["sp","Старик"],["v","Ваш первый был он предок из земли?",0,1000,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ему дала Паллада при рожденье…",0,1001,0,0],["sp","Старик"],["v","Что? Что дала? Не медли — говори!..",0,1002,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Две капельки… но крови из Горгоны.",0,1003,0,1],["sp","Старик"],["v","Но как же их ребенок сохранил?",0,1006,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","В златом кольце он дал их Эрехтею.",0,1007,0,0],["sp","Старик"],["v","И вслед за ним владеешь ими ты?",0,1008,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, и ношу на пальце, как ты видишь.<a class=\"nr\" href=\"#n-k37\" data-n=\"k37\" aria-label=\"Примечание 37\">37</a>",0,1009,0,0],["sp","Старик"],["v","Но этот дар двойной, каков же он?",0,1010,0,1],["sd","(Разглядывает снятое <span class=\"ch\" data-ch=\"kreusa\">Креусой</span> кольцо.)"],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Есть капля там одна из полой жилы…",0,1011,0,0],["sp","Старик"],["v","К чему ж она? Какая сила в ней?",0,1012,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Недуг целит и жизнь она питает.",0,1013,0,0],["sp","Старик"],["dir","продолжает со вниманием рассматривать"],["v","Ну, а другой-то сгусток, — тот зачем?",0,1014,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","пониженным голосом"],["v","Чтоб убивать… То яд из змей Горгоны…",0,1015,0,0],["sp","Старик"],["v","Слила ль ты их иль носишь разделив?..",0,1016,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нет, разделив. Да их и не смешаешь.",0,1017,0,0],["sp","Старик"],["v","Ты, дочь моя, теперь имеешь все…",0,1018,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Вот юноше посол и дар ему же.<a class=\"nr\" href=\"#n-k38\" data-n=\"k38\" aria-label=\"Примечание 38\">38</a>",0,1019,0,0],["sp","Старик"],["v","Но где и как? Начни, а кончу я.",0,1020,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","В Афинах, лишь ко мне он поселится…",0,1020,0,0],["sp","Старик"],["v","Теперь черед за мной тебя бранить.",0,1021,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Уж не мое ль тебя берет сомненье?",0,1022,0,0],["sp","Старик"],["v","Будь ты чиста, а скажут на тебя…",0,1023,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Да, мачехи детей не любят мужних.",0,1024,0,0],["sp","Старик"],["v","Убей, но здесь… и знать не знаю, мол…",0,1025,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Заранее вкушаю сладость мести.",0,1026,0,0],["sp","Старик"],["v","При том же царь бы вовсе и не знал,",0,1027,0,0],["v","Что ты его уж овладела тайной.",0,1028,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","снимая кольцо, передает его старику"],["v","Ты так поступишь, старец. Вот тебе",0,1029,0,0],["v","Старинное изделье золотое",0,1030,0,1],["v","Афинино. Ступай туда, где царь",0,1030,0,0],["v","Тайком справляет жертву. Там дождешься,",0,1031,0,0],["v","Как кончат гости пир и возливать",0,1032,0,0],["v","Бессмертным приготовятся, — плащом",0,1033,0,0],["v","Прикрывши яд, ты выплеснешь его",0,1033,0,0],["v","Царевичу в его отдельный кубок.",0,1034,0,0],["v","Смотри, не всем чтобы досталось. Он лишь,",0,1035,0,0],["v","Дворцом моим собравшийся владеть,",0,1036,0,0],["v","Мой выпить яд назначен. Капле ж этой",0,1036,0,0],["v","Достаточно смочить ему гортань,",0,1037,0,0],["v","И он кремля Афины не увидит.",0,1038,0,0],["sp","Старик"],["v","Вернись же в дом к друзьям своим, а мы",0,1039,0,0],["v","Потрудимся над этим порученьем.",0,1040,0,1],["v","Вы, ноги старые, для дела, так и быть,",0,925,0,0],["v","Помолодейте, пусть и непристойно",0,810,0,0],["v","Годам уж вашим это — для господ",0,694,0,0],["v","Врага авось настигнем, с ним покончим,",0,579,0,0],["v","Очистим дом. Счастливым, тем с руки",0,463,0,0],["v","Блюсти закон богов, а враг насядет —",0,348,0,0],["v","Так все тогда с пути законы прочь!<a class=\"nr\" href=\"#n-k11\" data-n=\"k11\" aria-label=\"Примечание 11\">11</a><a class=\"nr\" href=\"#n-k12\" data-n=\"k12\" aria-label=\"Примечание 12\">12</a>",0,232,0,0],["v","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> со свитой и старик расходятся со сцены.<a class=\"nr\" href=\"#n-k7\" data-n=\"k7\" aria-label=\"Примечание 7\">7</a>",0,117,0,0],["scene","Третий музыкальный антракт","s13",4,13],["sp","Хор"],["str","Строфа"],["v","О дочь Деметры, о ты,",0,1,0,1],["v","Царица путей!",0,2,0,0],["v","И ночью ты правишь след,<a class=\"nr\" href=\"#n-k36\" data-n=\"k36\" aria-label=\"Примечание 36\">36</a><a class=\"nr\" href=\"#n-k39\" data-n=\"k39\" aria-label=\"Примечание 39\">39</a>",0,3,0,0],["v","И днем его правишь, — кубок,",0,1050,0,1],["v","Где яд из тела Горгоны,",0,1051,0,0],["v","Землею рожденной, моя",0,1052,0,0],["v","Царица послала, тот кубок",0,1053,0,0],["v","Доправь до мужа, который",0,1054,0,0],["v","Возжаждал древнего трона…",0,1055,0,0],["v","Из дома ж иного никто",0,1056,0,0],["v","В Афинах сменить не дерзнет",0,1057,0,0],["v","Детей Эрехтеева рода.",0,1060,0,1],["str","Антистрофа I"],["v","Но если казни не быть,",0,1060,0,0],["v","Коль мимо — удар, —",0,1061,0,0],["v","И время и счастье, все,",0,1062,0,0],["v","Все мимо, — на выбор царице:",0,1063,0,0],["v","Иль меч, или петли узел…",0,1064,0,0],["v","По воле. Несчастьем моя",0,1065,0,0],["v","Царица покончит страданья",0,1066,0,0],["v","Для новой и лучшей жизни.",0,1067,0,0],["v","Но знаю: коль жить суждено ей,",0,1068,0,0],["v","Лучи ее глаз никогда",0,1069,0,0],["v","Не встретят чужого царя",0,1070,0,1],["v","В Афинах — она благородна.",0,1071,0,0],["str","Строфа II"],["v","Мне стыдно за Феба. О бог,",0,1072,0,0],["v","Прославленный в гимнах, неужто<a class=\"nr\" href=\"#n-k40\" data-n=\"k40\" aria-label=\"Примечание 40\">40</a>",0,1073,0,0],["v","Ты дашь, чтобы юный этот",0,1074,0,0],["v","В священную ночь при свете",0,1075,0,0],["v","Пылающих факелов видел,",0,1076,0,0],["v","Бессонный, эйкад танцы,",0,1077,0,0],["v","И хоры светил в эфире,",0,1078,0,0],["v","И в хоре мерцаний Селену,",0,1080,0,1],["v","Чтоб он дочерей Нерея",0,1081,0,0],["v","Увидел в сверканьях моря",0,1082,0,0],["v","И в черных круженьях виров",0,1083,0,0],["v","На вечных потоках, где славят",0,1084,0,0],["v","В венце золотом они Деву",0,1085,0,0],["v","И Матерь-царицу?.. О нет,",0,1086,0,0],["v","Бродяга пифийский этот",0,1087,0,0],["v","Царить там не будет, считая",0,1088,0,0],["v","Казну в сундуках афинских.",0,1089,0,0],["str","Антистрофа II"],["v","Глядите ж, поэты, и вы,",0,1090,0,1],["v","Что в гимнах певучих клянете",0,1090,0,0],["v","Неверности наши горько,",0,1091,0,0],["v","Киприды несытой страсти;",0,1092,0,0],["v","Глядите, насколько мы нравом",0,1093,0,0],["v","Распутства мужчин выше",0,1094,0,0],["v","Безбожных; стрелой певучей",0,1095,0,0],["v","Вы в них нацельте, о музы,",0,1095,0,0],["v","За брачный обман, а нам вы",0,1096,0,0],["v","Должны палинодию, музы!",0,1097,0,0],["v","Тот муж, нечестивый сердцем,<a class=\"nr\" href=\"#n-k41\" data-n=\"k41\" aria-label=\"Примечание 41\">41</a>",0,1098,0,0],["v","От Зевса сынов происшедший,",0,1099,0,0],["v","О прошлом забыл, должно быть…",0,1100,0,1],["v","Не с собственной делит женой",0,1101,0,0],["v","Он радость иметь ребенка;",0,1102,0,0],["v","Чужою Кипридою счастлив,",0,1103,0,0],["v","Он сына родил не дома.",0,1104,0,0],["act","Действие четвертое","a5","IV"],["scene","Явление десятое","s14",5,14],["v","Раб <span class=\"ch\" data-ch=\"ksuf\">Ксуфа</span> (со стороны города).",0,1105,0,0],["sp","Раб"],["v","О женщины, о гостьи! Где ж царица,",0,1106,0,0],["v","Дочь Эрехтея? Я по всем домам",0,1107,0,0],["v","Ее искал напрасно меж дельфийцев.",0,1108,0,0],["sp","Корифей"],["v","Товарищ по неволе! Чем же ты",0,1109,0,0],["v","Так окрылен? Слова несешь какие?",0,1110,0,1],["sp","Раб"],["v","За госпожою гонятся. Ее",0,1110,0,0],["v","Приговорили городские власти",0,1111,0,0],["v","Низвергнуть со скалы. И мы — за ней.",0,1112,0,0],["sp","Корифей"],["v","Увы! Увы! Что слышу? Или, тайно",0,1113,0,0],["v","Убить замыслив этого ребенка,",0,1114,0,0],["v","Подслушаны мы были кем-нибудь…",0,1115,0,0],["sp","Раб"],["v","О да, и ты поплатишься, наверно.",0,1115,0,0],["sp","Корифей"],["v","Но как на свет те козни вышли? Как?",0,1116,0,0],["sp","Раб"],["v","Неправду бог поставил ниже правды:",0,1117,0,0],["v","Не потерпел он этого пятна.",0,1118,0,0],["sp","Корифей"],["v","Но как? Тебя молю, не скрой, товарищ,",0,1119,0,0],["v","И умереть и видеть солнце нам",0,1120,0,1],["v","Отраднее, тебя услышав, будет.",0,1120,0,0],["sp","Раб"],["v","<span class=\"ch\" data-ch=\"kreusa\">Креусы</span> муж когда покинул храм,",0,1121,0,0],["v","С собой увел и найденного сына.",0,1122,0,0],["v","Он пир тогда ж замыслил, чтоб богов",0,1123,0,0],["v","Торжественным благодарить служеньем;",0,1124,0,0],["v","Сам в горы царь направился, где пламя",0,1125,0,0],["v","Диониса колеблется. Его",0,1125,0,0],["v","Он оросить сбирался кровью тельчей",0,1126,0,0],["v","Двуглавую вершину. Сыну ж так<a class=\"nr\" href=\"#n-k42\" data-n=\"k42\" aria-label=\"Примечание 42\">42</a>",0,1127,0,0],["v","Он приказал: \"Велишь шатры раскинуть",0,1128,0,0],["v","Ты мастерам, а если слишком я",0,1129,0,0],["v","За жертвою рождения промедлю,",0,1130,0,1],["v","Пусть без меня собравшимся гостям",0,1131,0,0],["v","Предложат пир\". И, взяв телиц, он отбыл,",0,1132,0,0],["v","А юноша тотчас же на столбах",0,1133,0,0],["v","Велит шатер без стен раскинуть, только",0,1134,0,0],["v","От пламени полудня защитив",0,1135,0,0],["v","Гостей да от закатного. Квадратный",0,1136,0,0],["v","То был шатер, по плефру сторона;<a class=\"nr\" href=\"#n-k44\" data-n=\"k44\" aria-label=\"Примечание 44\">44</a>",0,1137,0,0],["v","А площадью был десять тысяч футов,",0,1138,0,0],["v","Как говорят ученые. И зван",0,1139,0,0],["v","На пир был целый город. Для завесы ж",0,1140,0,1],["v","Священные дельфиец ткани взял",0,1140,0,0],["v","Среди сокровищ бога, — загляденье!",0,1141,0,0],["v","И первое крыло покровов — крыша,",0,1142,0,0],["v","Кронидова был сына дар. Отняв",0,1143,0,0],["v","Его от амазонок, сын Алкмены",0,1144,0,0],["v","Пожертвовал оракулу. И было",0,1145,0,0],["v","Там выткано узором, как Уран",0,1145,0,0],["v","В кругу эфирном собирает звезды,",0,1146,0,0],["v","И Гелиос на крайний запад пламя",0,1147,0,0],["v","Своей четверки гонит, а за ним",0,1148,0,0],["v","Влачится яркий Геспер; дальше Ночь",0,1149,0,0],["v","В одеждах черных и на колеснице,",0,1150,0,1],["v","Но лошади ярма не носят. Звезды<a class=\"nr\" href=\"#n-k45\" data-n=\"k45\" aria-label=\"Примечание 45\">45</a>",0,1150,0,0],["v","За Ночью вслед. Плеяда же как раз",0,1151,0,0],["v","Посередине неба. Орион",0,1152,0,0],["v","За ней оруженосцем, и созвездье",0,1152,0,0],["v","Медведицы, что повернула хвост",0,1153,0,0],["v","К златой звезде Полярной. Полным кругом",0,1154,0,0],["v","Горит луна в зените, и Гиады,",0,1155,0,0],["v","Предвестницы дождей, чье никогда<a class=\"nr\" href=\"#n-k46\" data-n=\"k46\" aria-label=\"Примечание 46\">46</a>",0,1155,0,0],["v","Явление пловца не обмануло, —",0,1156,0,0],["v","И Эос наконец, и перед ней",0,1157,0,0],["v","Бегут светила ночи.",0,1157,0,0],["v","По бокам",1,1157,0,0],["v","Шатра на тканях азиатских были",0,1158,0,0],["v","Их корабли написаны на веслах,",0,1159,0,0],["v","И эллинский в сраженье с ними флот,",0,1160,0,1],["v","Да люди-полузвери и охота",0,1160,0,0],["v","Их конная на ланей и на львов.",0,1161,0,0],["v","У входа же в шатер царя Кекропа",0,1162,0,0],["v","Пред дочерьми клубилось тело. Дар",0,1163,0,0],["v","Афинский, вероятно. Посредине",0,1164,0,0],["v","Шатра <span class=\"ch\" data-ch=\"ion\">Ион</span> кратеры разместить",0,1165,0,0],["v","Велел златые. И герольд, привставши<a class=\"nr\" href=\"#n-k43\" data-n=\"k43\" aria-label=\"Примечание 43\">43</a>",0,1166,0,0],["v","На цыпочки, провозгласил, что пир",0,1167,0,0],["v","Открыт для всех дельфийцев. Вслед палата",0,1168,0,0],["v","Наполнилась. И, головы венчав,",0,1169,0,0],["v","Дельфийцы приступили к пиру. Кончен",0,1170,0,1],["v","Уж был и пир, когда в шатер взошел",0,1170,0,0],["v","Старик. Держась посередине залы,",0,1171,0,0],["v","Он веселит гостей — так услужить",0,1172,0,0],["v","Старается им всячески, из кружек",0,1173,0,0],["v","Им подает он мыться, мирру жжет,",0,1174,0,0],["v","Заведует распределеньем кубков",0,1175,0,0],["v","И сам гостей обносит.",0,1175,0,0],["v","Между тем",1,1175,0,0],["v","Флейтисты появились, вслед и чаша",0,1176,0,0],["v","Пошла кругом. Но так сказал старик:",0,1177,0,0],["v","\"Ну, эту мелочь прочь бы. Чтоб веселье",0,1178,0,0],["v","Сюда пришло скорее, заменить",0,1179,0,0],["v","Большими надо кубки\". И на сцену",0,1180,0,1],["v","Являются чеканные сосуды",0,1180,0,0],["v","Из серебра и золота. Всех больший",0,1181,0,0],["v","Хозяину подносит молодому",0,1182,0,0],["v","Тогда старик, наполнив до краев.",0,1183,0,0],["v","Туда ж он влил и яд, царицей данный,",0,1184,0,0],["v","Чтоб новый сын ее глаза закрыл",0,1185,0,0],["v","Раз навсегда. Старик работал чисто.",0,1186,0,0],["v","⟨<em>Для возлиянья чашу взял <span class=\"ch\" data-ch=\"ion\">Ион</span>,</em>⟩",0,1187,0,0],["v","Да, на беду его, какой-то раб",0,1188,0,0],["v","Неладно тут сказал. Наш господин,<a class=\"nr\" href=\"#n-k47\" data-n=\"k47\" aria-label=\"Примечание 47\">47</a>",0,1189,0,0],["v","Который в храме вырос и искусных",0,1190,0,1],["v","Гадателей наслушался, слова",0,1190,0,0],["v","Те счел за знак дурной, и вот он новый",0,1191,0,0],["v","Велит наполнить чан. А сам вино",0,1192,0,0],["v","Готовое на землю льет и то же",0,1193,0,0],["v","Других он просит сделать. Воцарилось",0,1193,0,0],["v","Молчание, покуда мы водой",0,1194,0,0],["v","И Библоса вином спешим наполнить<a class=\"nr\" href=\"#n-k48\" data-n=\"k48\" aria-label=\"Примечание 48\">48</a>",0,1195,0,0],["v","Священный чан. Лишь стая голубей",0,1196,0,0],["v","Крылатая под сень влетела… В храм",0,1196,0,0],["v","Они летают смело. Пить ли им",0,1197,0,0],["v","Хотелось, но в разлитой влаге клювы",0,1198,0,0],["v","Купать они пустились тут и в горло",0,1199,0,0],["v","Пушистое вбирать ее. И сок",0,1200,0,1],["v","Диониса вреда не делал птицам.",0,1201,0,0],["v","Лишь та, что опустилась близ вина,",0,1202,0,0],["v","Разлитого <span class=\"ch\" data-ch=\"ion\">Ионом</span>, не успела",0,1203,0,0],["v","И клюв смочить, как крылья у нее",0,1204,0,0],["v","Затрепетали, задрожали ноги…",0,1205,0,0],["v","Кричать она, стонать… И вся толпа,",0,1206,0,0],["v","Оцепеневши, смотрит, как голубка",0,1207,0,0],["v","Кончается, и пурпурные ей",0,1208,0,0],["v","Смерть выпрямляет ноги.",0,1209,0,0],["v","Тут свой пеплос",1,1209,0,0],["v","Названый сын срывает, и, на стол",0,1210,0,0],["v","Вскочивши, он кричит:",0,1211,0,0],["v","\"Кто собирался",1,1211,0,0],["v","Меня убить? Эй, говори, старик,",0,1212,0,0],["v","Ты хлопотал, нам подавая кубок!\"",0,1213,0,0],["v","И за руку <span class=\"ch\" data-ch=\"ion\">Ион</span> хватает старца,",0,1214,0,0],["v","Чтоб взять его с поличным.",0,1215,0,0],["v","И старик",1,1215,0,0],["v","Был принужден открыть, что от царицы",0,1216,0,0],["v","Отрава та… Тут Локсия перстом",0,1217,0,0],["v","Указанный стремится из палаты,",0,1218,0,0],["v","А гости вслед. И судьям молвит он:",0,1219,0,0],["v","\"Священная земля, я был отравлен",0,1220,0,1],["v","Приезжей из Афин, — а дочь она",0,1220,0,0],["v","По крови Эрехтея\".",0,1221,0,0],["v","Власти ж Дельфов",1,1221,0,0],["v","Все, как один, решают со скалы",0,1222,0,0],["v","Царицу нашу свергнуть за попытку",0,1223,0,0],["v","Убить лицо священное — и в храме…",0,1224,0,0],["v","Весь город на ногах, да не найдут…",0,1225,0,0],["v","Давно ли в путь злосчастный поспешала?",0,1226,0,0],["v","Детей ей Феб был должен дать, — и вот",0,1227,0,0],["v","С надеждами и жизнь она теряет.",0,1228,0,0],["sp","Хор"],["v","Нет больше мне, нет от смерти,",0,1229,0,0],["v","Несчастной, спасенья, — нет!",0,1230,0,1],["v","Улика, улика — это",0,1230,0,0],["v","Убийство проклятой смесью",0,1231,0,0],["v","Из сока лозы и капель",0,1232,0,0],["v","Крови быстрой ехидны…",0,1233,0,0],["v","О, жертва богам поддонным —",0,1234,0,0],["v","Дни мои пожирающий ужас!",0,1235,0,0],["v","И царице моей кончина",0,1236,0,0],["v","Разбитой об острые камни…",0,1237,0,0],["v","Улететь… улететь бы на крыльях,",0,1238,0,0],["v","Затаиться в пещерный сумрак.",0,1239,0,0],["v","Как уйти нам от каменной смерти?",0,1240,0,1],["v","Поручить себя быстрым колесам",0,1241,0,0],["v","Иль корме корабля?.. Что делать?",0,1242,0,0],["v","О, куда ж я уйду, если бог",0,1243,0,0],["v","Из когтей у черной не вырвет…",0,1244,0,0],["v","Ты ж, царица, твой жребий! о, горе!",0,1245,0,0],["v","Мы хотели убить другого —",0,1246,0,0],["v","На краю могилы мы сами;",0,1247,0,0],["v","[О, неужто ж все это не сон?]<a class=\"nr\" href=\"#n-k49\" data-n=\"k49\" aria-label=\"Примечание 49\">49</a>",0,1248,0,0],["scene","Явление одиннадцатое","s15",5,15],["sd","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> в сопровождении небольшой свиты. В одежде ее беспорядок. Ее волосы распустились. При виде <span class=\"ch\" data-ch=\"kreusa\">Креусы</span> раб быстро уходит, стараясь сделать это незаметно."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О рабыни! О, спасите! Я на смерть осуждена,",0,1250,0,1],["v","Суд пифийский совершился — и меня сейчас казнят.",0,1251,0,0],["sp","Корифей"],["v","О твоих мы знаем муках и несчастье, госпожа.",0,1252,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Но куда ж бежать? Из сети я сейчас едва спаслась.",0,1253,0,0],["v","К вам украдкой я. Повсюду сторожат меня враги.",0,1254,0,0],["sp","Корифей"],["v","Вот алтарь, — куда же больше?",0,1255,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Чем поможет мне алтарь?",1,1255,0,0],["sp","Корифей"],["v","Грех убить того, кто молит.",0,1256,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Осудил меня закон.",1,1256,0,0],["sp","Корифей"],["v","Да, но пусть возьмут…",0,1257,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О, боги… Палачи… сюда… бегом.",1,1257,0,0],["sd","Приближается шум."],["v","Меч-то… наголо…",0,1258,0,0],["sp","Корифей"],["v","Прижмись же поскорее к алтарю…",1,1258,0,0],["v","Если здесь ты не спасешься, кровь падет на палачей",0,1259,0,0],["v","Карой тяжкою, царица, а судьбы не избежишь.",0,1260,0,1],["sd","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> припадает к алтарю. На сцену появляется толпа вооруженных людей с <span class=\"ch\" data-ch=\"ion\">Ионом</span> во главе. У <span class=\"ch\" data-ch=\"ion\">Иона</span> меч наголо."],["scene","Явление двенадцатое","s16",5,16],["sd","<span class=\"ch\" data-ch=\"ion\">Ион</span> и <span class=\"ch\" data-ch=\"kreusa\">Креуса</span>."],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","указывая на <span class=\"ch\" data-ch=\"kreusa\">Креусу</span>"],["v","Кефис-отец с лицом быка! какую",0,1260,0,0],["v","Ехидну возрастил ты иль змею<a class=\"nr\" href=\"#n-k50\" data-n=\"k50\" aria-label=\"Примечание 50\">50</a>",0,1261,0,0],["v","Какую, что глазами пламя мечет",0,1262,0,0],["v","Смертельное. Все дерзости слилися,",0,1263,0,0],["v","Все в ней одной — она страшней отравы",0,1264,0,0],["v","Из жил Горгоны, поднесенной мне.",0,1265,0,0],["sd","(К окружающим.)"],["v","Берите же ее, пусть эти косы",0,1265,0,0],["v","Зацепятся за острые каменья",0,1266,0,0],["v","Парнасских скал, когда катиться будет",0,1267,0,0],["v","По ним злодейка эта. Хорошо,",0,1268,0,0],["v","Что к мачехе такой я не успел",0,1269,0,0],["v","В афинский дом попасть. Уж если здесь,",0,1270,0,1],["v","Среди друзей, я должен был измерить",0,1271,0,0],["v","Несчастием всю силу этой злобы,",0,1272,0,0],["v","Так что ж бы там? Недолго бы пожить",0,1273,0,0],["v","Пришлося мне в Афинах…",0,1274,0,0],["v","О, тебе",1,1274,0,0],["v","Ни алтари, ни храмы не помогут,",0,1275,0,0],["v","А этот плач скорей бы подобал",0,1276,0,0],["v","Меня родившей или мне. Не с нами",0,1277,0,0],["v","Она, но имя матери со мной…",0,1278,0,0],["v","Коварство-то какое! Новый узел",0,1279,0,0],["v","Завязан на узле… Дрожит, обняв",0,1280,0,1],["v","Алтарь, и думает, что кара миновала.",0,1281,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Не смей меня касаться: ни меня,",0,1282,0,0],["v","Ни здесь со мной таящегося бога.",0,1283,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но ты и Феб? Что общего меж вас?",0,1284,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Священна я, как достоянье бога!",0,1285,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И собралась убить его слугу!",0,1286,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Иль Локсиев ты, если ты отцовский?",0,1287,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Феб сделался мне истинным отцом.",0,1288,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты был — его, я ж стала вещью Феба.",0,1289,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Нечестьем ты к нему приведена,",0,1290,0,1],["v","Я ж посвящен ему благочестиво.",0,1290,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты посягал на дом мой, и врага",0,1291,0,0],["v","В тебе убить хотела я по праву.",0,1292,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","С оружием на дом твой я не шел.",0,1293,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нет, шел и дом поджег ты Эрехтеев.",0,1294,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Где ж факелы? Откуда был огонь?",0,1295,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Вселиться в дом ты собирался силой.",0,1295,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Тот дом отец оружием добыл.",0,1296,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","При чем в стране Паллады род Эола?",0,1297,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ее мечом, не на словах он спас.",0,1298,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Он ей помог, но не владеет ею.",0,1299,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но… отравлять… возможного врага?!<a class=\"nr\" href=\"#n-k51\" data-n=\"k51\" aria-label=\"Примечание 51\">51</a>",0,1300,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Что ж, дать себя убить, щадя <span class=\"ch\" data-ch=\"ion\">Иона</span>?..",0,1300,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Из зависти все это, что отец",0,1301,0,0],["v","Меня нашел и ты одна бездетна…",0,1302,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Так у бездетных земли отнимать?",0,1303,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но у кого отец имеет тоже…<a class=\"nr\" href=\"#n-k52\" data-n=\"k52\" aria-label=\"Примечание 52\">52</a>",0,1304,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","прерывая его"],["v","Копье и щит получишь от отца.",0,1305,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Оставь алтарь! Покинь святое место!",0,1306,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Где мать твоя? Ты матери внушай.",0,1307,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Иль кары ты, злодейка, не потерпишь?",0,1308,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Здесь убивай, на самом алтаре.",0,1309,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Средь Фебовых венцов, но в чем тут радость?",0,1310,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Обидчику я злом за зло воздам.",0,1310,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Увы!",0,1311,0,0],["v","Печально, что бессмертные законов",0,1312,0,0],["v","Нам не дали разумнее. Алтарь",0,1313,0,0],["v","Не должен бы служить защитой дерзким,",0,1314,0,0],["v","И силой бы их надо отгонять…",0,1315,0,0],["v","Нельзя руке преступной прикасаться",0,1315,0,0],["v","До достоянья божьего, — одним",0,1316,0,0],["v","У алтаря должно быть место чистым,",0,1317,0,0],["v","Когда их обижают. А не то:",0,1318,0,0],["v","И праведный и злой — а бог за всех…",0,1319,0,0],["sd","(Большими шагами приближается к алтарю.)"],["scene","Явление тринадцатое","s17",5,17],["sd","Те же и Пифия (из средней двери). В руках у нее корзинка, перевязанная лентой."],["sp","Пифия"],["dir","к <span class=\"ch\" data-ch=\"ion\">Иону</span>"],["v","Остановись, дитя мое. Треножник",0,1320,0,1],["v","Покинувши свой вещий, я порог",0,1320,0,0],["v","Переступаю этот, бога Феба",0,1321,0,0],["v","Пророчица и меж дельфийских дев",0,1322,0,0],["v","Избранная блюсти закон гаданий.",0,1323,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","опускает меч"],["v","Привет тебе, хоть не по плоти, мать.",0,1324,0,0],["sp","Пифия"],["v","Я так зовусь, и имя мне отрадно.",0,1325,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","указывая Пифии на <span class=\"ch\" data-ch=\"kreusa\">Креусу</span>"],["v","Слыхала ль ты, каким коварством нас",0,1325,0,0],["v","Жена хотела эта уничтожить?",0,1326,0,0],["sp","Пифия"],["v","Я слышала. Но ты жесток, мой сын.",0,1327,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Иль должен я щадить свою убийцу?",0,1328,0,0],["sp","Пифия"],["v","Или одной ей пасынок постыл?",0,1329,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И мачеха не нам одним, надеюсь.",0,1330,0,1],["sp","Пифия"],["v","Пусть так, мой сын! Но все ж вернись домой.",0,1330,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Вернуться ж как, придумать не могу я…",0,1331,0,0],["sp","Пифия"],["v","Вернись в Афины чистый, и когда",0,1332,0,0],["v","Ты знаменье счастливое получишь…",0,1333,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А кровь врага не очищает нас?",0,1334,0,0],["sp","Пифия"],["v","Пускай других. К тебе ж я речь имею…",0,1335,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Что б ни сказала ты, во благо все.",0,1336,0,0],["sp","Пифия"],["v","Ты видишь — я в руках держу корзинку.",0,1337,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да, старая корзина — бант на ней.",0,1338,0,0],["sp","Пифия"],["v","В ней я нашла тебя новорожденным.",0,1339,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Что говоришь? Я этого не знал.",0,1340,0,1],["sp","Пифия"],["v","Молчала я, — теперь же открываю.",0,1340,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но почему ж так долго я не знал?",0,1341,0,0],["sp","Пифия"],["v","Феб не желал твоих услуг лишаться.",0,1342,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","И пожелал… Но знак мне надо, знак…",0,1343,0,0],["sp","Пифия"],["v","Какой же знак? Отцу тебя он отдал.",0,1344,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но колыбель хранить мою, — его ль",0,1345,0,0],["v","Имела ты приказ иль чей же, мать?",0,1346,0,0],["sp","Пифия"],["v","Мне бог внушил…",0,1347,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Внушил тебе… Но что же?",1,1347,0,0],["v","Докончи речь… Ты что-то начала…",0,1348,0,0],["sp","Пифия"],["v","…Найденное беречь… и до сегодня.",0,1349,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А в чем же мне здесь польза или вред?",0,1350,0,1],["sp","Пифия"],["v","Там детские лежат твои пеленки.",0,1350,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Иль я по ним родимую найду?",0,1351,0,0],["sp","Пифия"],["v","Коль этого захочет бог, не раньше…",0,1352,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О, призраки блаженства — все зараз…",0,1353,0,0],["sp","Пифия"],["v","Разыскивай же мать — следы имеешь…",0,1354,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Всю Азию, Европу обойду…",0,1355,0,0],["sd","(Принимает от Пифии корзину.)"],["sp","Пифия"],["v","Как знаешь сам. А я, по воле бога",0,1356,2,0],["v","Вскормив тебя, все отдала теперь,",0,1357,2,0],["v","Что Аполлон зажег во мне желанье",0,1358,2,0],["v","Хранить по этот день. Зачем зажег",0,1359,2,0],["v","Желанье он во мне, не знаю, — только",0,1360,2,1],["v","Из смертных ни один не знал, что я",0,1360,2,0],["v","Храню корзину эту, и храненья",0,1361,2,0],["v","От всех таилось место. Ну прощай!",0,1362,2,0],["sd","(Целует его.)"],["v","Люблю тебя, как мать. И все ж ты должен",0,1363,2,0],["v","Родимую отыскивать.",0,1364,2,0],["v","Ты здесь",1,1364,0,0],["v","Ищи сначала, в Дельфах, кто подкинуть",0,1365,2,0],["v","Тебя дерзнул, потом в Элладе. Я ж",0,1366,2,0],["v","И Аполлон все должное свершили.",0,1367,2,0],["sd","(Уходит, не оборачиваясь и неслышно, как тень.)"],["scene","Явление четырнадцатое","s18",5,18],["sd","Те же без Пифии."],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Увы! Увы! Зачем не в силах слез",0,1368,0,0],["v","Я удержать. Все думаю о том,",0,1369,0,0],["v","Как, после брака тайного, родивши",0,1370,0,1],["v","Меня, таясь, родимая сюда",0,1371,0,0],["v","Несла, и груди я искал напрасно.",0,1372,0,0],["v","Без имени, от бога взыскан только,",0,1373,0,0],["v","Судьбой же не обласкан, сколько дней,",0,1374,0,0],["v","Пока другой бы нежился в объятьях",0,1375,0,0],["v","У матери, я молока лишен",0,1376,0,0],["v","Был женского, отрадной этой пищи.",0,1377,0,0],["v","А мать была ль счастливее? Она",0,1378,0,0],["v","Ведь тоже не ласкала сына…",0,1379,0,0],["sd","Меч уже брошен. <span class=\"ch\" data-ch=\"ion\">Ион</span> приближается с корзиной к алтарю, и теперь <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> может хорошо видеть его ношу: она смотрит на корзину, не отрывая глаз."],["v","Эту",1,1379,0,0],["v","Все ж Фебу колыбель отдам… Найти",0,1380,0,1],["v","Так страшно нежеланное… Быть может,",0,1380,0,0],["v","Рабыней мать была… Свое покрыть",0,1381,0,0],["v","Молчанием рожденье иль бесславно",0,1382,0,0],["v","Удел узнать? Что лучше?",0,1383,0,0],["v","Аполлон!",1,1383,0,0],["v","Тебе мой дар, о бог! Но что со мною?",0,1384,0,0],["v","В борьбу вступил я с Фебом?.. Иль не он",0,1385,0,0],["v","Сберег нам эти знаки?..",0,1386,0,0],["v","Так смелей же",1,1386,0,0],["v","Покончим с этой тайной. Прочь завязки…",0,1387,0,0],["v","Что суждено, того не обойти…",0,1388,0,0],["sd","(Хочет развязать и останавливается.)"],["v","Священные завязки… Для чего же",0,1389,0,0],["v","Вы стерегли, скрывая от меня",0,1390,0,1],["v","Всю сладость жизни?.. Вот оно, плетенье",0,1391,0,0],["v","Моей корзинки круглой… Как она",0,1392,0,0],["v","От времени не подалась…Так долго",0,1393,0,0],["v","Она живет, но бог ее хранил…",0,1394,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","поднимается с места и протягивает руки к корзине"],["v","О безнадежный призрак!.. Ты ли?.. Ты ли?..",0,1395,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Молчи… Давно ты докучаешь нам…",0,1396,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","с загоревшимися глазами и с возрастающей энергией"],["v","Нет, я молчать не стану… И не требуй —",0,1397,1,0],["v","Я колыбель узнала.",0,1398,1,0],["v","Это я",1,1398,0,0],["v","Малюткою туда тебя вложила",0,1399,1,0],["v","В Кекроповой пещере, где скала",0,1400,1,1],["v","Нависла Макры.<a class=\"nr\" href=\"#n-k53\" data-n=\"k53\" aria-label=\"Примечание 53\">53</a>",0,1400,1,0],["sd","(Сходит со ступеней и быстро подходит к <span class=\"ch\" data-ch=\"ion\">Иону</span>.)"],["v","Видишь — я алтарь",0,1401,4,0],["v","Покинула; теперь меня казните.",0,1402,1,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","окружающим"],["v","Схватить ее… В ней разум исступлен",0,1403,0,0],["v","По воле Феба… Путайте ей руки.",0,1404,0,0],["sd","Вокруг некоторое движение, впрочем, неуверенное. Пользуясь им, <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> вцепляется в корзину."],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Казните… Но корзину я держу",0,1405,0,0],["v","И тем, что в ней таится, овладею…",0,1405,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О, ужас! О, бесстыднейший обман!",0,1406,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","у которой отняли корзину и которую в некотором расстоянии от алтаря держат за руки два стражника"],["v","Да нет же. Друг нашел тебя и счастлив.",0,1407,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты, ты — мне друг? Кто ж подсылал убийц?",0,1408,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты — плоть моя. Что ж может быть нам ближе?",0,1409,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Брось выдумки… Я уличу тебя…",0,1410,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","На это ж я и мечу… Испытай нас…",0,1411,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","садится на ступени алтаря со стороны противоположной той, где держат <span class=\"ch\" data-ch=\"kreusa\">Креусу</span>, чтобы она не могла видеть корзины"],["v","В корзине есть ли что-нибудь внутри?",0,1412,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Пеленки там должны были остаться.",0,1413,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Не видев их, сумеешь ли назвать?",0,1414,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Не назову — так умереть согласна.",0,1415,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ну, называй. Но дерзости дивлюсь.",0,1416,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Моей работы есть там одеяло…",0,1417,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","приоткрыв корзину, смотрит внутрь"],["v","Да мало ль ткут девицы одеял.",0,1418,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Не кончено оно — один набросок…",0,1419,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А что на нем?.. Нас этим не возьмешь…",0,1420,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Горгона там посередине ткани.",0,1421,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","не отвечая ей"],["v","О Зевс!.. Какой меня пытает жребий?",0,1422,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","А по бокам, как на эгиде, змеи…",0,1423,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","быстро сходит со ступеней и, обходя алтарь, показывает развернутую ткань окружающим."],["sd","По его знаку <span class=\"ch\" data-ch=\"kreusa\">Креусу</span> перестают держать. Но она не сходит с места и только издали любуется тканью, изредка протирая себе глаза, как бы после сна. Вокруг знаки удивления и восклицания."],["v","Вот эта ткань, как мы ее нашли…",0,1424,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О девичья… О давняя работа!",0,1425,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","возвращаясь на место"],["v","А дальше что ж?.. Угадано лишь раз…",0,1426,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Из золота литые два дракона.",0,1427,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","вынимая драконов, разглядывает их"],["v","Афинин дар иль детский амулет?",0,1428,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Об Эрихтонии живая память.",0,1429,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Но для чего же служит та краса?",0,1430,0,1],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Чтобы ребенку надевать на шею.",0,1431,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","показывая в высоко поднятой руке амулет"],["v","Драконы — вот… Но есть и третий знак.",0,1432,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я положила в колыбель с тобою",0,1433,0,0],["v","Из зелени оливковый венок…",0,1434,0,0],["v","Олива та, Афины насажденье,<a class=\"nr\" href=\"#n-k54\" data-n=\"k54\" aria-label=\"Примечание 54\">54</a>",0,1435,0,0],["v","Всегда цветет и не теряет листьев…",0,1436,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","вынув было венок, но роняет его на ступени и бросается в объятия <span class=\"ch\" data-ch=\"kreusa\">Креусе</span>"],["v","О мать, о дорогая, как лицо",0,1437,0,0],["v","Мне целовать твое отрадно, мама…",0,1438,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Дитя мое! О, ярче солнца свет",0,1439,0,0],["v","Из глаз твоих. Пусть бог меня простит.",0,1440,0,1],["v","Я обниму тебя, о мой нежданный…",0,1441,0,0],["v","А я уже оплакала тебя!..",0,1442,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Моя родная! Я зараз в объятьях",0,1443,0,0],["v","Твоих лежу и мертвый и живой.",0,1444,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","к Солнцу"],["v","Ио!.. В горящий эфир,",0,1445,0,0],["v","Всю радость из сердца в эфир",0,1446,0,0],["v","Сверкающий шлю я… Но речи?..",0,1447,0,0],["v","Откуда ж ты, счастье, и кто,",0,1448,0,0],["v","Кто дал тебя, радость?..",0,1449,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Да, все бы я подумал, но не это,",0,1450,0,1],["v","Не то, что я твой сын. Так был далек…",0,1450,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","От страха дрожу я еще.",0,1451,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты держишь меня и себе",0,1451,0,0],["v","Не веришь?..",0,1452,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О да,",1,1452,0,0],["v","Я потеряла все надежды…",0,1453,0,0],["sd","Пауза."],["sd","(К закрытой двери, за которую ушла Пифия.)"],["v","Гей, женщина!.. Откуда ж",0,1453,2,0],["v","Тебе дитя досталось?.. Кто его",0,1454,2,0],["v","Принес в святилище?",0,1455,2,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Оставим это богу… Усладимся",0,1455,0,0],["v","Наградою за прошлые несчастья.",0,1456,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","порывисто лаская <span class=\"ch\" data-ch=\"ion\">Иона</span>"],["v","О, не без слез ты достался мне!",0,1456,0,0],["v","Но от тебя",0,1457,3,0],["v","Как уходила я,",0,1458,3,0],["v","Больше я плакала…",0,1458,3,0],["v","К щеке твоей",0,1459,3,0],["v","Дай же прижаться мне… Да, я дышу тобой.",0,1460,0,1],["v","Счастья сильнее нет…",0,1460,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","закрыв глаза"],["v","Твои слова пускай за нас обоих…",0,1461,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нет, не бесплодна я… Нет, не бездетна…",0,1462,0,0],["v","В доме очаг горит… В Аттике — царь…",0,1463,0,0],["v","Старый вздымается корень,",0,1464,0,0],["v","Зазеленел он… Довольно",0,1465,0,0],["v","Этого мрака… Солнце",0,1466,0,0],["v","Дому открылось.",0,1467,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О мать! Зачем же ты с моим отцом,",0,1468,0,0],["v","Что дал тебе я, радость не разделишь?",0,1469,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","на коленях, прячет лицо в руках"],["v","Дитя, о, на что, о, на что ты меня осуждаешь!",0,1470,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Я не пойму.",0,1470,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["sd","Другой отец, другой…"],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О, горе… Ты была тогда девицей.",0,1471,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О нет… Не факелы",0,1472,0,0],["v","С танцами нежными",0,1473,0,0],["v","Брак веселили тот,",0,1474,0,0],["v","Где зародился ты.",0,1475,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Увы! Позор рожденья! Кто ж отец?",0,1476,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","вставая"],["v","Убийцу Горгоны ты знаешь?<a class=\"nr\" href=\"#n-k55\" data-n=\"k55\" aria-label=\"Примечание 55\">55</a>",0,1477,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","При чем же тут богиня, не пойму.",0,1478,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","в мрачном экстазе"],["v","Чей трон на родимых утесах,",0,1479,0,0],["v","Оливы ее там растут.",0,1480,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты говоришь так странно и неясно…",0,1481,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Под тою скалой, где поют соловьи",0,1482,1,0],["v","И с Фебом…",0,1483,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Феб при чем же? Говори.",1,1483,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нас тайное ложе связало.",0,1484,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Доканчивай, я вижу славу, счастье.",0,1485,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Десятой луне, от Феба тебя я",0,1486,0,0],["v","Тайно зачавши, явила…",0,1487,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О сладкие слова, коль правда в вас.",0,1488,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","В девичью работу свою",0,1489,0,0],["v","Тебя завернула я — мать,",0,1490,0,1],["v","Но груди тебе не дала",0,1491,0,0],["v","И губ молоком не смочила,",0,1492,0,0],["v","Тебя не омыла, и тут же",0,1493,0,0],["v","В пещере пустынной тебя",0,1494,0,0],["v","Оставила я, чтобы клювы",0,1495,0,0],["v","Тебя растащили, — Аиду",0,1496,0,0],["v","Дитя посвятила свое.",0,1497,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О! Что ты сделала, родная!",0,1498,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Я в страхе губила тебя, —",0,1499,0,0],["v","Тут не было воли.",0,1500,0,1],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А я был твой убийца нечестивый.",0,1501,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ужасны и прошлые беды,",0,1502,0,0],["v","И эти. Катились мы, ветром",0,1503,0,0],["v","Несчастья гонимы сюда,",0,1504,0,0],["v","Теперь подхватило нас счастье.",0,1505,0,0],["v","Дыханье сменилось… Но пусть",0,1506,0,0],["v","Оно остается. Несчастий",0,1507,0,0],["v","Довольно, и новый какой-то",0,1508,0,0],["v","Из бед поднимает нас ветер.",0,1509,0,0],["sp","Корифей"],["v","После того, что здесь произошло,",0,1510,0,1],["v","Никто терять надежды уж не смеет.",0,1510,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты, случай — бог; нас мириады здесь,",0,1511,0,0],["v","И каждого и каждый миг ты можешь",0,1512,0,0],["v","И мукою донять, и наградить",0,1513,0,0],["v","За прошлое. Сказать, что мне грозила",0,1514,0,0],["v","Сегодня смерть от матери и мог",0,1515,0,0],["v","Я стать ее убийцей… А за что?..",0,1515,0,0],["v","За складками ль эфира те таятся",0,1516,0,0],["v","Превратности, что можно испытать",0,1517,0,0],["v","Все за день нам? Мне случай приберег",0,1518,0,0],["v","Завидный дар — и мать, и род завидный…",0,1519,0,0],["v","Но подойди сюда.",0,1520,0,1],["sd","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span> подходит."],["v","Спросить тебя хочу — и будет тайным",0,1521,0,0],["v","Наш разговор. Родимая, смотри,",0,1522,0,0],["v","С девицами бывает ведь, что тайный",0,1523,0,0],["v","Их свяжет брак. Зачем же имя Феба",0,1524,0,0],["v","Примешивать, стараяся мое",0,1525,0,0],["v","Рожденье приукрасить, но, родив",0,1526,0,0],["v","Действительно ведь вовсе ж не от бога…",0,1527,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["dir","торжественно и поднимая руки к небу"],["v","Афиною клянусь я и ее",0,1528,0,0],["v","Победной колесницей, на которой",0,1529,0,0],["v","Гигантов Зевс осилил, что не муж,",0,1530,0,1],["v","Не смертный, а сам Локсий — твой отец…",0,1530,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Зачем же нас он дал отцу другому",0,1531,0,0],["v","И Ксуфовым рожденьем объявил?",0,1532,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Ты не рожден был <span class=\"ch\" data-ch=\"ksuf\">Ксуфом</span>, но в подарок",0,1533,0,0],["v","Ему дитя свое не мог ли Феб",0,1534,0,0],["v","Отдать? Иль друг не уступает другу",0,1535,0,0],["v","Своих детей в наследники порой?",0,1536,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","задумчиво"],["v","Правдив ли бог, или вещанье лживо,",0,1537,0,0],["v","Сомнением, о мать, смутился ум…",0,1538,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Послушай же, что мне на ум приходит…",0,1539,0,0],["v","Ведь Феб, тебе ж добра желая, в дом",0,1540,0,1],["v","Тебя такой назначил.",0,1540,0,0],["v","А считайся",1,1540,0,0],["v","Ты сыном бога, не иметь бы ввек",0,1541,0,0],["v","Ни имени отцовского, ни дома",0,1542,0,0],["v","Наследного тебе… Да разве брак",0,1542,0,0],["v","Я Фебов не таила? Даже сына",0,1543,0,0],["v","Убийцей чуть не сделалась… Так вот",0,1544,0,0],["v","Зачем отцу другому ты был отдан.",0,1545,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","А все-таки поверить нелегко…",0,1545,0,0],["v","Уж лучше же я сам спрошу у Феба,",0,1546,0,0],["v","Его ль я сын иль смертного отца.",0,1547,0,0],["v","Над крышей дома показывается Афина Паллада.",0,1547,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["dir","закрываясь"],["v","Ба… Это что ж? На доме средь курений",0,1548,0,0],["v","Чей это лик божественный, лучей",0,1549,0,0],["v","Сиянием исполнен? О родная,",0,1550,0,1],["v","Бежим скорей, чтоб демонов не видеть…",0,1550,0,0],["v","Глядеть на них не надо, говорят.",0,1551,0,0],["v","Хочет увести мать. Афина останавливает их знаком.",0,1552,0,0],["act","Исход","a6",""],["scene","Явление пятнадцатое","s19",6,19],["sd","Афина. <span class=\"ch\" data-ch=\"ion\">Ион</span>. <span class=\"ch\" data-ch=\"kreusa\">Креуса</span>."],["sp","Афина"],["v","Постойте ж вы… Не враг вам угрожает.",0,1553,0,0],["v","В Афинах ли иль здесь, но лишь добра",0,1554,0,0],["v","Желаю вам…",0,1555,0,0],["sd","<span class=\"ch\" data-ch=\"ion\">Ион</span> и <span class=\"ch\" data-ch=\"kreusa\">Креуса</span> останавливаются и молитвенно обращаются к Афине."],["v","Паллада — имя мне,",1,1555,0,0],["v","И я спешу от берегов, которым",0,1556,0,0],["v","Свое дала я имя. Не хотел",0,1557,0,0],["v","К вам на глаза являться Феб, и нас он<a class=\"nr\" href=\"#n-k56\" data-n=\"k56\" aria-label=\"Примечание 56\">56</a>",0,1558,0,0],["v","Сюда послал слова его поведать.",0,1559,0,0],["sd","(К <span class=\"ch\" data-ch=\"ion\">Иону</span>.)"],["v","Ты этою женою зачат был",0,1560,0,1],["v","От Локсия, так было, — только отдал",0,1560,0,0],["v","Тебя он не родившим, он к царю",0,1561,0,0],["v","В чертог его решил тебя направить.",0,1562,0,0],["v","Когда ж раскрылась тайна, убоясь,",0,1563,0,0],["v","Чтоб матерью не быть тебе убитым",0,1563,0,0],["v","Иль матереубийцею не стать,",0,1564,0,0],["v","Вас хитростями спас он. Собирался",0,1565,0,0],["v","Пока молчать бессмертный и открыть,",0,1566,0,0],["v","Лишь как придешь в Афины, что родился",0,1566,0,0],["v","От этой ты жены и от него.",0,1567,0,0],["v","Но чтоб свершить и дело и глаголы,",0,1568,0,0],["v","Те вещие, которые победили меня",0,1569,0,0],["v","Коней направить в Дельфы — вот обоим",0,1570,0,1],["v","И мой наказ.",0,1570,0,0],["sd","(<span class=\"ch\" data-ch=\"kreusa\">Креусе</span>.)"],["v","Веди отсюда сына",0,1571,4,0],["v","В Кекропов край, о Креуса, и там",0,1572,0,0],["v","Ему престол отдашь ты царский. Родом",0,1573,0,0],["v","Он — Эрехтид и над моей землей",0,1574,0,0],["v","Достоин быть царем. И он в Элладе",0,1575,0,0],["v","Прославится. От корня одного",0,1575,0,0],["v","Пойдут четыре сына — эпонимы",0,1576,0,0],["v","Для четырех племен того народа,",0,1577,0,0],["v","Что на моем теперь живет холме.",0,1578,0,0],["v","Гелеон будет первый, дальше племя",0,1579,0,0],["v","Гоплетское, Аргады, Эгикоры<a class=\"nr\" href=\"#n-k57\" data-n=\"k57\" aria-label=\"Примечание 57\">57</a>",0,1580,0,1],["v","(Так от моей Эгиды названы).",0,1581,0,0],["v","Со временем, назначенным заране,",0,1582,0,0],["v","Их сыновья Киклады заселят",0,1583,0,0],["v","И побережье моря, — все оплотом",0,1584,0,0],["v","Моей стране избранное служить, —",0,1585,0,0],["v","Рассеявшись и по азийским гладям,",0,1586,0,0],["v","И против них в Европе… Имя ж им",0,1587,0,0],["v","От этого — ионяне и будет,",0,1588,0,0],["v","Прославленное имя…",0,1589,0,0],["v","<span class=\"ch\" data-ch=\"ksuf\">Ксуф</span> и ты",1,1589,0,0],["v","Родите вместе Дора, и Дорида",0,1590,0,1],["v","Пойдет оттуда светлая, второй",0,1590,0,0],["v","Ваш будет сын — Ахей — в земле Пелопа…",0,1591,0,0],["v","И станет он царем приморья Рия<a class=\"nr\" href=\"#n-k58\" data-n=\"k58\" aria-label=\"Примечание 58\">58</a>",0,1592,0,0],["v","Поблизости, а именем его",0,1593,0,0],["v","Отметится народ.",0,1594,0,0],["v","Как мудро Локсий",1,1594,0,0],["v","Устроил все, смотрите. Раньше ты",0,1595,0,0],["v","Без мук родила сына, — так что близкий",0,1595,0,0],["v","И тот не знал. Потом, когда, родив",0,1596,0,0],["v","И завернув в пеленки, ты дитя",0,1597,0,0],["v","Оставила, он приказал Гермесу",0,1598,0,0],["v","Сюда снести ребенка на руках",0,1599,0,0],["v","И воспитал, не дав ему погибнуть…",0,1600,0,1],["v","А все ж молчи о том, что сын тобой",0,1600,0,0],["v","Рожден, пускай приятней <span class=\"ch\" data-ch=\"ksuf\">Ксуфу</span> будет",0,1601,0,0],["v","Его считать своим. С тебя, жена,",0,1602,0,0],["v","Довольно, что с тобою сын. Простите ж…",0,1603,0,0],["v","От мук теперь вздохните, а судьба",0,1604,0,0],["v","Счастливою отныне будет ваша.",0,1605,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","О Паллада, дочь Кронида и царя среди богов,",0,1606,0,0],["v","Как словам твоим не верить, что поистине она",0,1607,0,0],["v","Зачала меня от Феба, — так и можно было ждать.",0,1608,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","Нас послушай тоже. Феба я хвалю, а до сих пор",0,1609,0,0],["v","Не хвалила. Раньше сыном нашим он пренебрегал,",0,1610,0,1],["v","А теперь его мне отдал. Храм и эта дверь его —",0,1610,0,0],["v","Все теперь мне улыбнулось, и от злобы — ни следа…",0,1611,0,0],["v","Поднимаю к кольцам руки и приветствую врата…<a class=\"nr\" href=\"#n-k60\" data-n=\"k60\" aria-label=\"Примечание 60\">60</a>",0,1612,0,0],["sp","Афина"],["v","Ты права, переменившись и что бога хвалишь ты:",0,1613,0,0],["v","Боги медленны в решеньях, все же воля их тверда.",0,1614,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","О дитя, Афины ждут нас.",0,1615,0,0],["sp","Афина"],["v","В путь же… А за вами я.",1,1615,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Ты достойнейший нам спутник.",0,1616,0,0],["sp","<span class=\"ch\" data-ch=\"kreusa\">Креуса</span>"],["v","И Афин старинный друг.",1,1616,0,0],["sp","Афина"],["v","Дам тебе престол я древний.",0,1617,0,0],["sp","<span class=\"ch\" data-ch=\"ion\">Ион</span>"],["v","Достоянья выше нет…",1,1617,0,0],["v","Афина исчезает. Со сцены все уходят.",0,1618,0,0],["sp","Хор"],["dir","покидает орхестру"],["v","Сын Кронида и Латоны, здравствуй, вышний Аполлон!",0,1619,0,0],["v","Если чтит богов достойно и в несчастье человек,",0,1620,0,1],["v","Пусть надежды не теряет. Добрый будет награжден.",0,1621,0,0],["v","Только злым, покуда злые, счастья в жизни не видать.<a class=\"nr\" href=\"#n-k59\" data-n=\"k59\" aria-label=\"Примечание 59\">59</a>",0,1622,0,0],["h1","Комментарий","comm"],["p","Время написания трагедии документально не засвидетельствовано. Однако искусное построение интриги, включающей «узнавание» матери и сына, пристальный интерес к психологической характеристике персонажей и некоторые стилистические признаки заставляют датировать «Иона» периодом от 412 до 408 г. до н. э. Сказание о происхождении Иона — родоначальника афинян — принадлежало к числу местных аттических преданий и до Еврипида было отчасти обработано только в не дошедшей до нас трагедии Софокла «Креуса»."],["ed","В.Н. Ярхо"],["note","k1"],["note","k2"],["note","k3"],["note","k4"],["note","k5"],["note","k6"],["note","k7"],["note","k8"],["note","k9"],["note","k10"],["note","k11"],["note","k12"],["note","k13"],["note","k14"],["note","k15"],["note","k16"],["note","k17"],["note","k18"],["note","k19"],["note","k20"],["note","k21"],["note","k22"],["note","k23"],["note","k24"],["note","k25"],["note","k26"],["note","k27"],["note","k28"],["note","k29"],["note","k30"],["note","k31"],["note","k32"],["note","k33"],["note","k34"],["note","k35"],["note","k36"],["note","k37"],["note","k38"],["note","k39"],["note","k40"],["note","k41"],["note","k42"],["note","k43"],["note","k44"],["note","k45"],["note","k46"],["note","k47"],["note","k48"],["note","k49"],["note","k50"],["note","k51"],["note","k52"],["note","k53"],["note","k54"],["note","k55"],["note","k56"],["note","k57"],["note","k58"],["note","k59"],["note","k60"]],"n":{"k1":["Ст. 6. Срединный храм","см. примеч. к «Медее», ст. 668. <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>«Медея», Ст. 668. Серединный храм.</b> храм с прорицалищем Аполлона в Дельфах; в качестве алтаря служил камень конической формы, который греки считали «пупом Земли», т. е. ее центром.</span><!--/xn-->"],"k2":["Ст. 20 — 26. Рожденный Землей","Эрихтоний, будущий афинский царь, рожденный, согласно аттическому сказанию, Землей и Гефестом; он был принят Афиной и в закрытом ларце передан ею трем дочерям царя Кекропа (по матери Аглавре их называли Аглавридами) со строгим запретом открывать ларец. Аглавриды, ослушавшись воли Афины, открыли ларец и увидели там младенца, и с ним змей,их приставила к нему Афина, чтобы напитать Эрихтония пищей бессмертия. Обезумев от страха при виде этого зрелища, Аглавриды бросились со скал Акрополя и разбились (см. ст. 267 — 274). Первую половину этого сказания Еврипид использует здесь для объяснения афинского обычая снабжать новорожденных мальчиков амулетами в виде змей."],"k3":["Ст. 30. …Людей тех самородных…","Еврипид называет афинян, потомков Эрихтония, «самородными» (автохтонами), так как они ведут происхождение от своей собственной земли."],"k4":["Ст. 53. …А как подрос…","Об исполнении Ионом обязанностей хранителя храмовых сокровищ дальше нигде не вспоминают."],"k5":["Ст. 60. Халкодонт («меднозубый»)","имя древнего царя Евбеи; в «Илиаде», II, 541, его сын Элефенор упоминается среди греческих вождей, приведших свои дружины под Трою."],"k6":["Ст. 70 — 71. …в Афинах он и Креусой признан был…","Узнавание Иона Креусой происходит в трагедии Еврипида в Дельфах. В ст. 71 сл. поэт, очевидно, воспроизводит более ранний вариант сказания."],"k7":["Ст. 82 — 183","Монодии Иона в оригинале предшествуют анапесты (ст. 82 — 111)."],"k8":["Ст. 95. К серебру кружений касталийских…","Касталией назывался священный источник на Парнасе, вблизи которого расположены Дельфы. После ст. 101. Ремарка: «Лук и колчан со стрелами» примыслены Анненским на основании ст. 155 — 185; но гораздо вероятнее, что Ион угрожал птицам лишь словами. Образцом Анненского была соответственная сцена из пьесы Леконта де Лиля «Аполлонид» на сюжет «Иона»."],"k9":["Ст. 159. Вестник Кронидов","орел."],"k10":["Ст. 168. На делийских озерах…","На Делосе находилось круглое озеро, у которого Лето, по преданию, родила Аполлона и Артемиду. Здесь лебеди считались священными птицами."],"k11":["Ст. 183 — 233","Хор вводится совершенно искусственно, под предлогом осмотра достопримечательностей храма (ср. тот же прием в «Ифигении в Авлиде»), — вернейший признак того, как уже мало нужен Еврипиду хор в качестве участника действия. Какая деталь украшения храма обозначается как «близнецы над воротами», до сих пор остается неясным. Затем прислужницы видят рельефы на фризе, изображающие (ст. 192 — 200) бой Геракла с лернейской Гидрой (Иолай помогал Гераклу, прижигая факелом шеи Гидры, с которых были срублены головы), и (ст. 201 — 204) сражение Беллерофонта с Химерой. Наконец, внимание хора привлекает мраморный фронтон, на котором изображена битва богов с гигантами (ст. 205 — 218). Фрагменты этого фронтона найдены во время раскопок в Дельфах в конце прошлого века."],"k12":["Ст. 219 — 237","Антистрофа II не дает полного ритмического соответствия строфе II, даже если исключить из метрического рисунка антистрофы речевые реплики Иона; возможно, что дошедший до нас текст испорчен."],"k13":["Ст. 277 — 282. …другой рассказ…","Намек на трагедию Еврипида «Эрехтей», поставленную около 421 г., — чтобы спасти родину во время войны с элевсинским царем Евмолпом, Эрехтей принес в жертву богам свою дочь (или, как здесь сказано, дочерей) и благодаря этому сразил в единоборстве Евмолпа, сына Посейдона. За это, однако, разгневанный Посейдон ударил Эрехтея своим трезубцем, и афинский царь был поглощен разверзшейся землей на афинском акрополе. Долгие скалы, где Креусу взял в любовницы Аполлон, — пещера на северном склоне того же акрополя."],"k14":["Ст. 290 — 298. …он не наш…","Так как Ксуф — по происхождению эолиец, то для афинян, гордившихся своей «автохтонностью», было особенно необходимо получить предка из аттической земли; сын Аполлона и Креусы, дочери Эрехтея, вполне отвечал такого рода требованиям (ср. ст. 589 сл.)."],"k15":["Ст. 300. Трофоний","герой, имя которого носило прорицалище в мрачной пещере в Беотии."],"k16":["Ст. 371. Профет","прорицатель (греческое слово, которое Анненский пытался ввести в русский язык)."],"k17":["Ст. 378 — 380","Мысль, впервые высказанная Соленом в его известной элегии «К музам» (фр. 1, ст. 9 — 13): Ежели боги богатство дадут, оно прочным бывает От глубочайших корней вплоть до вершины самой. Если же дерзостью люди берут, не по чести приходит, Несправедливым делам будет служить и тогда Против желанья. Но быстро приходит беда роковая."],"k18":["Ст. 419 — 420","Буквально: «уже заколота общая жертва Аполлону от всех пришедших за вещаниями»: собственно, Ксуф должен был бы принести отдельную жертву, но это задержало бы действие."],"k19":["Ст. 456. Блаженная Победа","Афина-Ника, символизирующая славу города афинян."],"k20":["Ст. 550 — 552. Славя Вакховы огни.","Речь идет о празднествах в честь Диониса (Вакха), справлявшихся раз в два года на склонах Парнаса; едва ли, однако, в них могли принимать участие мужчины. Фиас — процессия в честь божества, чаще всего — в честь Вакха."],"k21":["Ст. 559","Зевсу внук я… — Собственно, правнук, так как сам Ксуф был внуком Зевса (см. ст. 63 и 292)."],"k22":["Ст. 603. И черепки влиятельных мужей…","Т. е. «голоса»: в демократических Афинах при голосовании об изгнании врагов народа («остракизме») имена писались на черепках. У Еврипида этого анахронизма нет, он внесен Анненским."],"k23":["Ст. 660. Идущий","народная этимология непонятного (догреческого) корня «Ион»."],"k24":["Ст. 666. А вам, рабыни, цепи на уста!","частый в античной трагедии случай, когда действующие лица призывают хор к сохранению тайны, — здесь, однако, хор нарушает свои обязательства (см. ниже, ст. 754 — 807)."],"k25":["Ст. 672 — 675. …номой язык свободен…","Еврипид вкладывает в уста Иону рассуждение об афинской «парресии» — праве свободно высказывать в народном собрании свое мнение; это право распространялось только на полноправных граждан, происходящих от афинян."],"k26":["Ст. 724. Гостей Эрехтея","Ксуфа с его дружиной."],"k27":["Ст. 859 — 922","Монодия Креусы, составляющая по композиции близкую аналогию к монодии Электры в «Оресте» (ст. 960 — 1012): за вступительным лирическим трехстишием (ст. 859 — 861) следует монолог в анапестах (ст. 862 — 880; своеобразие размера переводчиком не передано), к которому присоединяются три лирические строфы."],"k28":["Ст. 872. …Тритониды водою обильной.","Одна из версий мифа называла местом рождения Афины берега Тритонского озера в Ливии (ср. Эсхил, «Евмениды», ст. 292 сл.); так пытались объяснить древний эпитет богини «Тритогения»."],"k29":["Ст. 883. …Где рога бездушье стонет…","Речь идет, по-видимому, о полых рогах, завершавших сверху основание лиры и служивших резонаторами звука."],"k30":["Ст. 899 сл. …Где связал… ты меня ненавистным ярмом…","Аполлон запретил Креусе под страхом смерти разглашать тайну ее беременности (см. выше, ст. 14 сл.)."],"k31":["Ст. 908. Сын Латои…","Аполлон; богиня — мать его по-гречески звалась Лето, по-латыни Латоной."],"k32":["Ст. 919. Ненавидит, о Феб, тебя Делос…","Так как Аполлон, по мнению Креусы, предал рожденного им сына, она призывает на него ненависть острова Делоса, где его родила Лето."],"k33":["Ст. 988. Флегра","поле мифического сражения богов с гигантами; его локализовали обычно на полуострове Халкидика."],"k34":["Ст. 990. Чтобы богам пришлося потрудней.","Так как гиганты — дети Земли, то, произведя на свет Горгону, Земля пыталась этим оказать помощь своим сыновьям в их борьбе с богами. Дальнейшее изложение мифа о гибели Горгоны отличается от общеизвестной версии."],"k35":["Ст. 996 — 997. …Эгидою зовут… прянула в сражение…","Еврипид сближает греческое слово aigis, обозначающее одновременно «вихрь, бурю» и панцирь Афины, с глаголом aisso — «устремляться», «бросаться»."],"k36":["Ст. 1004 — 1005","изымаются как позднейшая вставка, предваряющая содержание ст. 1010 — 1015. Перевод их: «Как на людей-то действуют они? — Одна мертвит, другая исцеляет»."],"k37":["Ст. 1007 — 1009","В подлиннике речь идет не о кольце, а о пряжке (может быть, запястье)."],"k38":["Ст. 1019","Точнее: «вот от чего он умрет, а умертвишь его ты»."],"k39":["Ст. 1048 сл","О дочь Деметры, о ты, царица путей! — Еврипид отождествляет Гекату с «дочерью Деметры» — Персефоной."],"k40":["Ст. 1074 — 1089. О бог, прославленный в гимнах…","Иакх, аграрное божество, входившее наряду с Деметрой и Персефоной (славят… Деву и Матерь-царицу) в троицу, в честь которой справлялись Элевсинские празднества. Священная процессия отправлялась с афинской агоры в Элевсин, в двадцатый день («эйкады») месяца боэдромия. Присутствие на этих празднествах чужеземца неизвестного происхождения, каким кажется хору Ион, должно, по мнению афинянок, оскорбить Иакха."],"k41":["Ст. 1098. Палинодия","букв.: «обратная песнь», в которой опровергается содержание ранее сложенной песни. Ст. 1090 — 1098 близки по содержанию к песне хора в «Медее», ст. 410 — 430."],"k42":["Ст. 1125 — 1127","…Дионисову скалу он оросить сбирался кровью тельчей… — В благодарность Аполлону Ксуф устраивает пиршество в Дельфах, почтить же Диониса (см. примеч. к ст. 550 сл.) он отправляется высоко в горы, ближе к двуглавой вершине Парнаса. Поскольку это не близкий путь, получает мотивировку достаточно искусственное устранение Ксуфа из дальнейших событий (ст. 1128 — 1131). <br class=\"xb\"><span class=\"xn\"><i class=\"xa\">↳</i> <b>Ст. 550 — 552. Славя Вакховы огни..</b> Речь идет о празднествах в честь Диониса (Вакха), справлявшихся раз в два года на склонах Парнаса; едва ли, однако, в них могли принимать участие мужчины. Фиас — процессия в честь божества, чаще всего — в честь Вакха.</span><!--/xn-->"],"k43":["Ст. 1132 — 1166","В подробном описании шатра и украшающих его ковров естественно видеть изображение резиденции афинского «священного посольства» в Дельфах; такие «делегации» регулярно посылались всеми греческими городами-государствами для участия в празднествах, справлявшихся в честь Аполлона в Дельфах и на Делосе, в честь Посейдона — на Истмийском перешейке, близ Коринфа. Для украшения шатра Ион взял священные ткани среди сокровищ бога, то есть из сокровищницы афинян, которые имели в Дельфах свое святилище. Соответственно и дар Кронидова сына — Геракла, отнятый у амазонок с помощью Тесея (см. «Гераклиды», ст. 216), могли видеть в Дельфах современники Еврипида, но никак не спутники Ксуфа: по мифологической генеалогии, Тесей и Геракл поколения на три-четыре моложе участников трагедии."],"k44":["Ст. 1137. Плефр","мера длины, равная 30,83 м (100 футов)."],"k45":["Ст. 1151. Но лошади ярма не носят…","Точнее «без пристяжных» (и, вероятно, не лошадей, а волов)."],"k46":["Ст. 1156. Гиады, предвестницы дождей.","Восхождение семизвездия Гиад (в созвездии Тельца) предвещало в Греции начало периода дождей и зимних бурь, когда морское плавание становилось опасным."],"k47":["Ст. 1188 — 1193. …раб… неладно тут сказал…","Возлиянию богам должно было сопутствовать благочестивое молчание, тем более могло оскорбить Аполлона возлияние, сопровождаемое бранным словом. Поэтому Ион и велит налить в кубки нового вина."],"k48":["Ст. 1195. И Библоса вином…","Вино из финикийского города Библоса издавна считалось в Греции одним из самых ценных."],"k49":["Ст. 1244 — 1249","О, куда же я уйду… — В подлиннике песнь хора завершается анапестическими стихами, составляющими эффектный контраст к взволнованным трохеям (ст. 1250 — 1260)."],"k50":["Ст. 1261","Кефис, бог одноименной реки, протекающей в Средней Греции, считался предком Креусы по материнской линии. Как речного бога, его представляли в образе быка или человека с бычьей головой."],"k51":["Ст. 1300 сл","Неточный перевод. Смысл оригинала: «Ты хотела убить меня, опасаясь моих намерений? — Чтобы мне не погибнуть, если ты их осуществишь»."],"k52":["Ст. 1304","Точнее: «А мне удела нет в добре отцовском?»"],"k53":["Ст. 1401. Скала… Макры","те Долгие Скалы, о которых упоминалось в ст. 12."],"k54":["Ст. 1435. Олива та, Афины насаждены…","Речь идет о священной оливе на Акрополе, по преданию, посаженной Афиной во время ее спора с Посейдоном за первенство в Аттике."],"k55":["Ст. 1477. Убийцу Горгоны ты знаешь?","То есть Афину, помогшую Персею одолеть Горгону; ее голову богиня поместила затем на свой щит — эгиду."],"k56":["Ст. 1557. Не хотел… являться Феб…","Следующий стих, «чтобы ты не попрекнула его за прошлое», оставлен Анненским без перевода."],"k57":["Ст. 1578 — 1581. Гелеоны, Гоплеты, Аргады, Эгикоры.","названия древнейших родовых объединений в Аттике, которые афиняне, естественно, производили от четырех сыновей Иона — предка всех ионийцев. Так объяснялось и название Ионии — прибрежной полосы Малой Азии, заселенной греками, и приоритет афинян в ее древнейшей колонизации (см. ст. 1582 — 1588). К афинской царевне Креусе возводит Еврипид и происхождение дорийцев, правда, предком их является уже не афинянин, а эолийский царь Ксуф (ст. 1589 — 1594)."],"k58":["Ст. 1592. Рий (Рион)","мыс на северном побережье Ахайи."],"k59":["Ст. 1606 — 1622","Необычное для Еврипида завершение трагедии трохеическими тетраметрами. Из всех известных нам древнегреческих трагедий этот прием применяется еще только в «Агамемноне» Эсхила."],"k60":["Ст. 1612. …к кольцам.","Имеются в виду кольца, ввернутые в створки дверей храма."]},"mainEnd":2565,"c":[{"id":"ion","name":"Ион","role":"Сын Аполлона и Креусы, храмовый служка в Дельфах","intro":"Подкидыш, выросший при храме и не знающий своих родителей.","arc":"Ион — юноша чистый и наивный: он метёт храм, отгоняет птиц и поёт гимн Фебу. Встреча с Креусой и рассказ о брошенном ребёнке впервые заставляют его усомниться в справедливости богов. Признанный Ксуфом как сын, он боится стать чужаком в Афинах. Чуть не отравленный Креусой, он сам готов убить её у алтаря — и только колыбель, принесённая Пифией, открывает правду.","st":[{"i":224,"p":9,"l":"Пролог · явление второе","t":"Утро в храме","d":"Метёт храм лавровой метлой и поёт гимн Фебу, радуясь своей службе.","c":"","k":false},{"i":624,"p":24,"l":"Действие первое · явление четвертое","t":"Встреча с Креусой","d":"Расспрашивает царицу об Афинах; слышит историю о «подруге», брошенный ребёнок которой от Феба пропал.","c":"Впервые сомневается в богах.","k":false},{"i":706,"p":28,"l":"Действие первое · явление шестое","t":"Упрёк богам","d":"Наедине говорит, что боги, преследующие смертных за насилие, сами виновны в том же.","c":"","k":true},{"i":1102,"p":43,"l":"Действие второе · явление восьмое","t":"Признан Ксуфом","d":"Ксуф объявляет его своим сыном по слову оракула. Ион сомневается и боится жизни в Афинах.","c":"","k":false},{"i":2042,"p":80,"l":"Действие четвертое · явление двенадцатое","t":"У алтаря","d":"Узнав о заговоре, преследует Креусу и хочет оторвать её от алтаря.","c":"","k":false},{"i":2141,"p":84,"l":"Действие четвертое · явление тринадцатое","t":"Колыбель","d":"Пифия отдаёт ему колыбель, в которой его нашли.","c":"Путь к узнаванию.","k":true},{"i":2461,"p":96,"l":"Действие четвертое · явление четырнадцатое","t":"Узнавание матери","d":"Креуса называет вещи в колыбели — Ион узнаёт в ней мать.","c":"","k":false},{"i":2564,"p":100,"l":"Исход · явление пятнадцатое","t":"Слово Афины","d":"Афина подтверждает, что он сын Аполлона и родоначальник ионийцев.","c":"","k":false}],"gen":"Ион"},{"id":"kreusa","name":"Креуса","role":"Царица Афин, дочь Эрехтея","intro":"Мать, которая когда-то бросила ребёнка от Аполлона и теперь ищет ответа у оракула.","arc":"Креуса — одна из самых трогательных героинь Еврипида. Её монодия — обличение Аполлона, насильника и обманщика. Узнав, что муж будто бы нашёл сына, она в ревности и отчаянии решается на отравление юноши, но, спасаясь, находит в нём своего сына.","st":[{"i":624,"p":24,"l":"Действие первое · явление четвертое","t":"Разговор с Ионом","d":"Рассказывает «историю подруги», брошенной Фебом с младенцем.","c":"","k":false},{"i":1664,"p":65,"l":"Действие третье · явление девятое","t":"Обличение Аполлона","d":"Узнав, что сын достался Ксуфу, открывает всю правду о насилии бога и решается отравить юношу.","c":"От отчаяния к преступлению.","k":true},{"i":1938,"p":76,"l":"Действие четвертое · явление одиннадцатое","t":"Бегство","d":"Заговор раскрыт; приговорённая к смерти, укрывается у алтаря.","c":"","k":false},{"i":2461,"p":96,"l":"Действие четвертое · явление четырнадцатое","t":"Узнавание","d":"Узнаёт колыбель и описывает её содержимое — и обнимает сына.","c":"","k":true}],"gen":"Креуса"},{"id":"ksuf","name":"Ксуф","role":"Муж Креусы","intro":"Чужеземный царь, получивший афинский престол браком.","arc":"Ксуф прост и радушен; поверив оракулу, он счастлив обрести сына и решает выдать его за гостя, чтобы не огорчить жену.","st":[{"i":1102,"p":43,"l":"Действие второе · явление восьмое","t":"Мнимый сын","d":"По оракулу признаёт Иона своим сыном и обнимает его.","c":"","k":true}],"gen":"Ксуф"}]};
